-- ===== 본문 재추출 반영 3/5 (parse800.py 생성) =====
-- 러닝헤더가 끼어든 본문/뒤바뀐 본문을 PDF에서 다시 추출한 값으로 교체. id·코스·진도는 그대로.
-- 이 파일 70행 / 전체 338행

UPDATE public.words SET meaning = '세계경제포럼(WEF, 다보스포럼)은 저명한 기업인, 경제학자, 언론인, 정치인들이 모여세계 경제를 개선하기 위한 과제를 토론하고 연구하는 회의체이다.', detailed_meaning = '세계경제포럼(WEF, 다보스포럼)은 저명한 기업인, 경제학자, 언론인, 정치인들이 모여세계 경제를 개선하기 위한 과제를 토론하고 연구하는 회의체이다. 본부는 스위스 제네 바에 있으나 매년 1~2월경 스위스 동부의 다보스에서 연차총회가 개최되기 때문에 다보스포럼(Davos Forum)이라고도 불린다. 1971년 클라우스 슈바브(Klaus Schwab) 교수에 의해 창설되어 비영리재단 형태로 운영되고 있다. 애초에는 유럽의 기업경영자들이 참석하는 유럽경영포럼(European Management Forum)으로 출발하였으나 1973년부터참석 대상을 전 세계로 확대한 데 이어 1974년에는 정치지도자를 처음으로 초청하였다. 1976년에 회원 기준을 세계의 1,000개 선도 기업으로 하는 회원제도를 도입하였고 1987년에는 명칭을 세계경제포럼(WEF; World Economic Forum)으로 변경하였다. WEF는 초청된 인사들에게만 참석을 허용하고 초청받지 않은 참석자는 적지 않은 참석비를 내야 하는 등 배타적인 모임의 성격을 갖고 있다. WEF는 연차총회 외에 지역별, 산업별 회의를 운영하고 있는데 2004년 6월 서울에서 지역별 회의(WEF 아시아 전략회의)가 개최된 바 있다. 2025년에는 세계경제포럼과의 협약에 따라 경기도에 4차산업혁명센터가 설립되었다. WEF가 매년 발간하는 주요 보고서로는 글로벌 리스크 보고서, 글로벌 성별격차 보고서, 미래 직업 보고서 등이 있다.', related_words = '{}'::text[] WHERE id = 300;  -- 세계경제포럼(다보스포럼)
UPDATE public.words SET meaning = '세계국채지수(WGBI)는 영국의 FTSE 러셀이 발표하고 있는 주요국 국채로 구성된 국채지수로서 미국 등 주요 선진국 국채를 포함하고 있는 대표적인 채권부문 글로벌 지수이 다.', detailed_meaning = '세계국채지수(WGBI)는 영국의 FTSE 러셀이 발표하고 있는 주요국 국채로 구성된 국채지수로서 미국 등 주요 선진국 국채를 포함하고 있는 대표적인 채권부문 글로벌 지수이 다. 특히, WGBI는 블룸버그·바클레이즈 글로벌 종합지수(BBGA) 및 JP Morgan 신흥국국채지수(GBI-EM) 등과 함께 세계 3대 채권지수로 분류되고 있으며, 추종자금의 규모 및구성 종목의 안정성 등의 측면에서 대표적인 채권부문 선진국 지수로 알려져 있다. 2025 년 7월 말 현재 WGBI는 주요 선진국 및 중국, 멕시코, 말레이시아 등 총 25개국 국채를 포함하고 있으며, 각 국별 지수 비중은 해당국 국채 시가총액 비중에 따라 결정된다. WGBI 신규 편입은 매년 두 차례 진행되는 정기 리뷰 과정을 통해 진행된다. 일반적인 경우 편입가능성이 높을 것으로 예상되는 국가는 FTSE 러셀의 채권시장 국가분류 보고서의 WGBI 관찰대상국 리스트에 등재되며, 이후 편입기준 충족 여부를 확인한 후 정식 편입 발표가 진행된다. FTSE 러셀이 제시하고 있는 WGBI 편입기준은 시장 규모 및 국가 신용도 등 정량적 기준과 더불어 해당국 시장접근성을 평가하고 있는 정성적 기준이 적용된다. 예를 들어 신규 편입을 위해서는 국채 발행잔액 기준(500억달러) 및 국가 신용등급(S&P 기준 ‘A-’) 등의 최소 조건을 충족하여야 하며, 시장접근성 기준의 경우에는 FTSE의 채권시장 국가분류 레벨 ‘2’이상의 등급이 요구된다. 한국 국채는 2026년 4월부터 지수에 편입되기 시작하여 2026년 11월에 최종 편입이 완료될 예정이다. 대표적인 선진 채권지수인 WGBI 편입은 관련 추종자금의 유입과 더불어 국채시장 및 외환시장 안정성 제고에도 기여할 것으로 예상된다. 특히 WGBI 추종자금의 경우 상대적으로 자금 유출입의 변동성이 낮은 투자자 비중이 높다는 점에서 국채시장의 안정적 자금조달 기반을 제공할 것으로 판단되며, 우리나라 국채시장의 대외신인도 제고를 통해 이른바 ‘원화채 디스카운트’ 해소에도 도움이 될 것으로 기대된다.', related_words = ARRAY['국채 신뢰도']::text[] WHERE id = 301;  -- 세계국채지수(WGBI)
UPDATE public.words SET meaning = '세계은행그룹(World Bank Group)을 구성하는 5개 기구 중에서 국제부흥개발은행(IBRD)과 국제개발협회(IDA)를 합쳐서 부르는 명칭이다.', detailed_meaning = '세계은행그룹(World Bank Group)을 구성하는 5개 기구 중에서 국제부흥개발은행(IBRD)과 국제개발협회(IDA)를 합쳐서 부르는 명칭이다. IBRD는 제2차 세계대전으로 인한 재해 복구 및 개발도상국의 경제개발을 위한 장기개발자금 지원을 목적으로 1945 년 12월 설립되었으며 미국 워싱턴에 본부를 두고 있다. IBRD와 IDA는 별개의 법인체지만 IBRD의 임원이 IDA의 임원을 겸임하고 있으며 실무 집행부서도 별도의 구분 없이 세계은행으로 통합되어 운영되고 있다. 설립 초기에는 전쟁 복구 지원에 주력하였으나 이후 저소득 개발도상국의 경제·사회 개발을 위한 장기자금 융자 등 지원 분야를 확대하였다. IBRD 가입자격은 국제통화기금(IMF) 회원국에만 부여되고 가입 시 출자금을 납입해야 한다. 2025년 6월 말 현재 회원국은 189개국이며 우리나라는 1955년 8월에 가 입하였다. IDA는 1950년대 후반 최빈개발도상국 지원 필요성이 부각됨에 따라 저소득회원국의 경제개발 촉진 및 생활수준 향상을 위한 자금 지원을 목적으로 1960년 9월 발족하였다. IDA 가입자격은 IBRD 회원국에게만 부여되며 가입 시 출자금을 내야 한다. 2025년 6월 현재 회원국은 174개국이며 우리나라는 1961년 5월에 가입하였다.', related_words = ARRAY['국제통화기금(IMF)']::text[] WHERE id = 303;  -- 세계은행(World Bank)
UPDATE public.words SET meaning = '소득분배의 불평등도를 나타내는 지표의 하나로 전체 가구를 소득 수준의 순서에 따라 20%씩 5등분으로 나눈 다음, 소득 상위 20%(5분위) 계층의 평균소득을 소득 하위 20%(1 ㅅ분위) 계층의', detailed_meaning = '소득분배의 불평등도를 나타내는 지표의 하나로 전체 가구를 소득 수준의 순서에 따라 20%씩 5등분으로 나눈 다음, 소득 상위 20%(5분위) 계층의 평균소득을 소득 하위 20%(1 ㅅ분위) 계층의 평균소득으로 나눈 값이다. 소득5분위배율 값이 커질수록 고소득층과 저소득층 간의 소득분배가 악화하였음을 의미한다.', related_words = ARRAY['상대적 빈곤율','지니계수']::text[] WHERE id = 304;  -- 소득5분위배율
UPDATE public.words SET meaning = '소득교역조건지수는 순상품교역조건지수에 수출물량지수를 곱하여 {(수출물가지수/수입물가지수)×수출물량지수} 산출하는 것으로서 수출 총액으로 수입할 수 있는 상품의 양이 기준시점 대비 얼마나', detailed_meaning = '소득교역조건지수는 순상품교역조건지수에 수출물량지수를 곱하여 {(수출물가지수/수입물가지수)×수출물량지수} 산출하는 것으로서 수출 총액으로 수입할 수 있는 상품의 양이 기준시점 대비 얼마나 증가하였는지를 의미하며 순상품교역조건지수가 가격변동만을 고 려하는 단점을 보완해 준다. 예를 들어, 2024년 12월 소득교역조건지수 118.27은 수출총액으로 수입할 수 있는 상품의 양이 2020년 1~12월의 평균 대비 18.27% 증가하였음 을 의미한다. 순상품교역조건지수와 소득교역조건지수를 동시에 고려하면 수출입 상품의 가격변동뿐만 아니라 수출물량 변동까지 고려할 수 있어 교역조건을 보다 정확히 파악할수 있다.', related_words = ARRAY['순상품교역조건지수']::text[] WHERE id = 305;  -- 소득교역조건지수
UPDATE public.words SET meaning = '소비행태를 설명하는 상대소득가설은 소비가 현재소득 이외에도 과거의 최고 소득수준또는 타인의 소비수준과 같은 상대적인 요인에 의해서도 영향을 받을 수 있다는 가능성을 고려한다.', detailed_meaning = '소비행태를 설명하는 상대소득가설은 소비가 현재소득 이외에도 과거의 최고 소득수준또는 타인의 소비수준과 같은 상대적인 요인에 의해서도 영향을 받을 수 있다는 가능성을 고려한다. 이 가설에 따르면 현재소득이 과거의 최고 소득수준에 비해 작아지더라도 소비자는 소비를 소득감소에 비례하여 줄이지 않고 이보다 작은 폭으로 줄이게 되는 소비의 비가역성이 발생하게 된다. 이러한 소비의 비가역성으로 인해 발생하는 톱니효과 (Ratchet effect)는 단기적으로 소득이 변동할 경우 한계소비성향은 일정하지만 평균소비성향은 낮아지는 소비행태를 설명하는 핵심요소로 작용한다. 아울러 장기적으로 소득이 늘어날 경우 평균 및 한계소비성향이 같아지는 장기소비 행태도 설명 가능하다. 참고 로 상대소득가설에서 타인의 소비수준에 영향을 받는 현상인 전시효과(Demonstration effect)도 장단기 소비행태를 설명하는데 유용한 개념이라 하겠다.', related_words = ARRAY['한계소비성향']::text[] WHERE id = 308;  -- 소비의 비가역성
UPDATE public.words SET meaning = '소비자의 경기나 생활형편 등에 대한 주관적인 판단과 전망, 미래의 소비지출계획 등을 설문조사를 통해 지수화한 것으로, 기업들의 경제를 보는 시각이 반영된 기업경기실사지수(BSI; Business', detailed_meaning = '소비자의 경기나 생활형편 등에 대한 주관적인 판단과 전망, 미래의 소비지출계획 등을 설문조사를 통해 지수화한 것으로, 기업들의 경제를 보는 시각이 반영된 기업경기실사지수(BSI; Business Survey Index)와 함께 대표적인 경제심리지수 중 하나이다. 우리나라의 소비자동향지수(CSI; Consumer Survey Index)는 한국은행이 매월 15일을 전후한 일주일에 걸쳐 전국의 2,500여 가구를 대상으로 4부문 19개 항목을 조사한 후 하순경 발표하고 있다. 동 CSI는 5점 척도로 이루어져 있고 아래와 같이 항목별로 가중치를 부여하여 작성되며 지수의 기준치는 100으로 지수는 최저 0에서 200까지의 값을 갖는다. 지수가 100보다 큰 경우 경제상황을 긍정적으로 보는 소비자가 부정적으로 보는 소비자보다 더 많다는 것을 의미하며 100보다 작은 경우는 그 반대를 나타낸다. 지수가 0이면 모든 소비자가 경제상황을 부정적으로 본다는 뜻이고 지수가 200이면 모두 긍정적으로 본다는 의미가 된다. (매우긍정 × 1.0 + 다소긍정 × 0.5 - 다소부정 × 0.5 - 매우부정 × 1.0) CSI = × 100 + 100 전체 응답 가구 수CSI는 소비자들의 경제심리를 조사함으로써 경제에서 큰 비중을 차지하고 있는 민간소비지출의 변화를 예상해 볼 수 있게 하고 소비자들의 물가 전망을 조사하여 통화정책 수립에 중요한 기초정보를 제공한다는 점에서 유용한 경제지표이다.', related_words = ARRAY['경제심리지수','기업경기실사지수(BSI)']::text[] WHERE id = 309;  -- 소비자동향지수(CSI)
UPDATE public.words SET meaning = '소형모듈원자로(Small Modular Reactor)는 기존 대형 원전(1,000~1,500MW 출력)보다 출력 규모를 줄이고, 공장에서 모듈 단위로 제작한 뒤 현장에서 조립·설치하는 방식의', detailed_meaning = '소형모듈원자로(Small Modular Reactor)는 기존 대형 원전(1,000~1,500MW 출력)보다 출력 규모를 줄이고, 공장에서 모듈 단위로 제작한 뒤 현장에서 조립·설치하는 방식의 원자력 발전소를 말한다. 원자로, 증기발생기, 냉각재 펌프, 가압기 등 주요 기기를 하나의 용기에 일체화한 소형 원자로이다. 일반적으로 출력은 300MW(국제원자력기구 기준 소형) 이하로 설계되며, 모듈화된 구조로 건설 기간을 단축하고 비용을 절감할 수 있다. SMR은 소규모 전력망 지역이나 산업 단지 등 다양한 수요에 맞춤형 공급이 가능하다. 또한 풍력, 태양광 등 재생에너지의 간헐성을 보완하는 이산화탄소 배출이 없는 백업 전원으로 활용이 가능하여 탄소중립 목표달성에도 기여할 수 있다. 외부 전력으로 냉각펌프를 작동시켜야 하는 대형 원전과는 달리 자연 순환 냉각방법을 이용하므로 안전성도 높다. 이런 장점으로 인해 주요국은 SMR 기술개발과 실증, 상용화를 위해 연구개발투자를 확대하고 있다.', related_words = '{}'::text[] WHERE id = 314;  -- 소형모듈원자로(SMR)
UPDATE public.words SET meaning = '수요견인 인플레이션(Demand-Pull Inflation)이란 경기과열 등으로 인해 개인들의 재화나 서비스에 대한 수요가 크게 늘면서 상대적으로 부족해진 재화 및 서비스의 물가가 지속적으로', detailed_meaning = '수요견인 인플레이션(Demand-Pull Inflation)이란 경기과열 등으로 인해 개인들의 재화나 서비스에 대한 수요가 크게 늘면서 상대적으로 부족해진 재화 및 서비스의 물가가 지속적으로 상승하게 되는 것을 말한다. 수요견인 인플레이션은 생산요소시장과 생산물시장 모두에서 초과수요가 발생할 때 특히 분명하게 나타난다. 확대재정정책, 과도한 통화량 증가, 민간소비나 투자의 갑작스러운 변동에 따른 수요충격 등은 총수요를 증가시켜 수요견인 인플레이션을 발생시킨다. 예컨대 정부가 침체에 빠진 경기를 부양하기 위해서 정부지출을 확대하고 세율을 인하하는 등의 급격한 확대재정정책을 시행하였다면 총수요가 증가하여 수요견인 인플레이션이 발생할 수 있다.', related_words = ARRAY['비용인상 인플레이션']::text[] WHERE id = 316;  -- 수요견인 인플레이션
UPDATE public.words SET meaning = '수출입물가지수는 수출 및 수입상품의 가격변동을 측정하는 지표로서 동 지수는 대외의 ㅅ존도가 높은 우리나라의 경우 수출입상품의 가격변동이 국내물가, 생산활동 및 대외 경쟁등에 미치는 효과를 사전에', detailed_meaning = '수출입물가지수는 수출 및 수입상품의 가격변동을 측정하는 지표로서 동 지수는 대외의 ㅅ존도가 높은 우리나라의 경우 수출입상품의 가격변동이 국내물가, 생산활동 및 대외 경쟁등에 미치는 효과를 사전에 측정하기 위해 작성되며 주로 수출입관련업체들의 수출채산성 변동이나 수입원가 부담 등을 파악하는 한편 수출입물가지수의 상호 비교를 통하여 가 격측면에서의 교역조건 등을 측정하는 데 이용된다. 2025년 8월 기준으로 조사대상품목이 수출물가지수는 212개, 수입물가지수는 237개이며, 조사되는 가격기준은 수출 FOB, 수입 CIF를 원칙으로 하고 있다.', related_words = ARRAY['수출입물량지수']::text[] WHERE id = 322;  -- 수출입물가지수
UPDATE public.words SET meaning = '무역지수 중 수출입물량의 변동을 나타내 주는 것으로 수출입금액지수를 수출입물가지수로 나누어 사후적으로 산출되는데 이러한 방식으로 산출되는 것은 수출입금액이 가격요 인과 물량요인의 합과 일치한다는', detailed_meaning = '무역지수 중 수출입물량의 변동을 나타내 주는 것으로 수출입금액지수를 수출입물가지수로 나누어 사후적으로 산출되는데 이러한 방식으로 산출되는 것은 수출입금액이 가격요 인과 물량요인의 합과 일치한다는 점에서 타당성을 가진다고 할 수 있다. 수출입물량지수는 원유 등의 가격이 변화함에 따라 수출입액이 큰 폭의 변동을 보이는 경우 동 가격요인을 제외한 물량기준으로 우리나라의 수출입상황을 파악하는데 활용되는 지표이다.', related_words = ARRAY['수출입물가지수']::text[] WHERE id = 323;  -- 수출입물량지수
UPDATE public.words SET meaning = '어떤 생산물을 만드는 데 필요한 자본·노동·토지 등의 생산요소 가운데 자본과 토지는 일정하게 유지하고 노동의 투입량을 증가시킬 경우, 생산물 전체는 증가하지만 추가로 투입되는 노동량 1단위당', detailed_meaning = '어떤 생산물을 만드는 데 필요한 자본·노동·토지 등의 생산요소 가운데 자본과 토지는 일정하게 유지하고 노동의 투입량을 증가시킬 경우, 생산물 전체는 증가하지만 추가로 투입되는 노동량 1단위당 생산물의 증가는 차차 감소한다는 법칙이다. 수확체감의 법칙(Law of Diminishing Returns)은 원래 농지에서 작업하는 노동자 수의 증가에 대한 1인당 수확량의 증가와 관련된 것이었으나 이후 모든 산업부문에서 특정 생산요소의 투입량이 고 정된 단기에 발생하는 현상으로 확장되었고 “한계생산력 체감의 법칙”으로 일반화되었다.', related_words = ARRAY['한계비용']::text[] WHERE id = 324;  -- 수확체감의 법칙
UPDATE public.words SET meaning = '2008년 글로벌 금융위기 시 신용경색으로 금융시장 기능이 마비되면서 자금조달이나 만 기연장이 어려워짐에 따라 많은 은행들이 만기불일치 등에 따른 유동성 위기를 경험하였고 이는 금융시스템 전체의', detailed_meaning = '2008년 글로벌 금융위기 시 신용경색으로 금융시장 기능이 마비되면서 자금조달이나 만 기연장이 어려워짐에 따라 많은 은행들이 만기불일치 등에 따른 유동성 위기를 경험하였고 이는 금융시스템 전체의 유동성 경색을 유발하였다. 이에 따라 바젤위원회(BCBS)는 유동성 위기에 대한 대응 및 금융복원력 강화를 위해 단기 유동성 규제인 유동성커버리지비율과 함께 중장기 유동성 규제인 순안정자금조달비율(NSFR; Net Stable Funding Ratio)을 도입하였다. 순안정자금조달비율은 유동성을 감안한 은행 보유자산대비 안정적 조달자금(자본 및 부채)의 비율이며 은행들은 2018년부터 NSFR 비율을 100% 이상으로 유지하여야 한다. 즉, NSFR은 은행 자금조달 구조의 안정성을 강화하기 위해 장기 운용자산의 일정 부분을 안정적인 부채·자본으로 조달하도록 함으로써 은행들이 단기 도매자금조달에 과도하게 의존하는 행태를 제한하기 위해 도입되었다. NSFR의 산식은 ‘가 용 안정자금 조달금액(∑부채 및 자본항목잔액 × ASF 가중치) / 필요 안정자금 조달금액(∑자산항목잔액 × RSF 가중치) × 100’이다. 분자인 가용 안정자금 조달금액(ASF; Available Stable Funding)은 부채 및 자본 항목 중 향후 1년 이내 이탈 가능성이 낮은 안정적인 자금조달 금액을 의미한다. 분모인 필요 안정자금 조달금액(RSF; Required Stable Funding)은 자산항목 중 향후 1년 이내 현금화되기 어려워 안정적인 자금조달이 요구되는 금액을 말한다.', related_words = ARRAY['유동성리스크']::text[] WHERE id = 326;  -- 순안정자금조달비율
UPDATE public.words SET meaning = '순이체한도(Net Debit Cap)는 금융결제원의 차액결제시스템에 참가하고 있는 각 참가기관으로 하여금 여타 참가기관과의 CD, 타행환 거래 등에서 발생하는 순이체액(지급지시송신액 -', detailed_meaning = '순이체한도(Net Debit Cap)는 금융결제원의 차액결제시스템에 참가하고 있는 각 참가기관으로 하여금 여타 참가기관과의 CD, 타행환 거래 등에서 발생하는 순이체액(지급지시송신액 - 지급지시수신액)에 대하여 그 상한을 설정토록 함으로써 결제불이행 사태의 발생 가능성 및 불이행 규모를 최소화하도록 한 제도이다. 순이체한도의 적용을 받는 차액결제시스템은 한은금융망을 통하여 차액결제되고 있는 거래중 지급지시가 실시간으로 송수신되고 금융기관 간 결제보다 고객앞 대금지급이 먼저 이루어짐으로써 미결제순채무가 발생하는 타행환공동망, 전자금융공동망, 지방은행공동망, 국가간ATM망과 어음교환시스템, CD공동망, B2C 전자상거래 중 지급지시가 실시간으로 송수신되는 거래이다. 차액결제 대상거래로서 지급지시가 실시간으로 이루어지지 않는 지로시스템, 직불카드공동망등은 순이체한도 설정 대상에서 제외된다. 순이체한도는 각 차액결제 참가기관이 자신의 과거 최대 순채무액, 향후 대고객 거래규모의 변화 등을 종합적으로 고려하여 자율적으로 설정하도록 하고 있다.', related_words = ARRAY['결제리스크','차액결제시스템']::text[] WHERE id = 328;  -- 순이체한도제
UPDATE public.words SET meaning = '은행권의 위조방지를 위한 장치의 하나로 은행권 용지를 빛에 비췄을 때 여백에 숨겨진문양이 나타나도록 하는 장치를 말한다.', detailed_meaning = '은행권의 위조방지를 위한 장치의 하나로 은행권 용지를 빛에 비췄을 때 여백에 숨겨진문양이 나타나도록 하는 장치를 말한다. 기술적으로는 은행권 용지를 제작할 때 특정 부분의 두께와 밀도를 달리하면 부분적으로 용지의 얇음과 두꺼움이 달라지게 되며 이로 인해 빛의 투과정도가 달라져 빛에 비췄을 때 명암 차이가 문양으로 드러나게 된다. 현재 우리나라 각 은행권의 앞면에는 화폐도안 인물 초상 모양의 숨은 그림이 있는데, 오만원권에는 신사임당, 만원권에는 세종대왕, 오천원권에는 율곡 이이, 천원권에는 퇴계 이황이 나타난다.', related_words = ARRAY['은선']::text[] WHERE id = 329;  -- 숨은 그림(은화)
UPDATE public.words SET meaning = '우리나라는 자유변동환율제도를 채택하고 있어서 환율이 원칙적으로 외환시장에서 자율적으로 결정되도록 하고 있으나, 일시적인 수급불균형이나 시장 불안심리 등으로 환율이 급변동하는 경우에 한해 외환당국이', detailed_meaning = '우리나라는 자유변동환율제도를 채택하고 있어서 환율이 원칙적으로 외환시장에서 자율적으로 결정되도록 하고 있으나, 일시적인 수급불균형이나 시장 불안심리 등으로 환율이 급변동하는 경우에 한해 외환당국이 외환시장에 개입하여 환율변동 속도를 조절하게 되는데 이를 스무딩오퍼레이션(Smoothing Operation)이라 한다. 즉 단기간에 환율이 급격하게 하락할 경우 외환당국이 외환시장에서 원화를 대가로 미달러화를 매입함으로써미달러화의 초과공급(원화의 초과수요)을 흡수하여 원화의 절상 속도를 줄일 수 있고, 이 와는 반대로 환율이 급등하는 경우에는 외환당국이 외환시장에서 원화를 대가로 미달러화를 매각하여 미달러화의 초과수요(원화의 초과공급)를 흡수하여 원화의 절하 속도를 조절할 수 있다.', related_words = ARRAY['외환시장','고정환율제도/자유변동환율제도','평가절상/평가절하']::text[] WHERE id = 330;  -- 스무딩오퍼레이션
UPDATE public.words SET meaning = '스왑(SWAP)은 거래 쌍방이 미리 정한 계약조건에 따라 현재 시점에서 원금, 이자 등을 서 로 교환하기로 하고 일정 기간 주기적으로 원금이나 이자 등 현금흐름(cash flow)을 서로 교환하는', detailed_meaning = '스왑(SWAP)은 거래 쌍방이 미리 정한 계약조건에 따라 현재 시점에서 원금, 이자 등을 서 로 교환하기로 하고 일정 기간 주기적으로 원금이나 이자 등 현금흐름(cash flow)을 서로 교환하는 파생상품 계약을 말한다. 스왑 거래의 예로는 서로 다른 통화의 일정 원금만 교환하는 외환스왑(FX swap), 서로 다른 통화의 일정 원금과 이에 대한 이자의 지급을 교환하는 통화스왑(currency swap), 동일 통화의 일정 원금에 대해 서로 다른 이자(예: 변동금리와 고정금리)를 교환하는 이자율스왑(interest rate swap) 등이 있다. 통화스왑의 가 장 대표적인 형태는 거래 시작 시 원금을 교환한 뒤 만기 시 다시 원래 통화로 재교환하는 구조이다. 기간 중에는 각자 받은 통화에 해당하는 이자를 거래상대방에게 지급한다. 이 를 통해 환율 및 금리 위험을 관리할 수 있다. 이자율스왑은 금융시장 참가자들이 이자율변동 위험을 최소화하고 자금 운용의 안정성을 높이는 핵심 파생상품이다. 이자율스왑의 단순한 예를 들면 A기업은 변동금리 대출을 갖고 있어 이자율 상승이 걱정되고, B은행은 고정금리 대출로 인해 이자수익이 일정해 시장 상황 반영이 어렵다고 느낀다. 이때 A와 B가 이자율스왑을 체결하면, A는 B에게 고정금리로 이자를 지급하고, B는 A에게 변동금리로 이자를 지급하게 되어 A는 대출 이자 변동 위험에서 벗어나고 B는 변동성 있는 수익을 얻게 된다.', related_words = ARRAY['금리스왑','통화스왑']::text[] WHERE id = 331;  -- 스왑
UPDATE public.words SET meaning = '스왑레이트(Swap Rate)는 현물환율 대비 선물환율과 현물환율의 차이(=(선물환율-현물환율)/현물환율)를 연율(%)로 표시한 것으로 이론적으로는 양 통화 간 금리차와 일치 (covered', detailed_meaning = '스왑레이트(Swap Rate)는 현물환율 대비 선물환율과 현물환율의 차이(=(선물환율-현물환율)/현물환율)를 연율(%)로 표시한 것으로 이론적으로는 양 통화 간 금리차와 일치 (covered interest rate parity)하게 된다. 스왑레이트는 금융기관의 자금사정을 나타내는 대용지표(proxy)로도 활용된다. 예를 들어 국내 금융기관의 외화자금사정이 악화되면 금융기관은 외화조달의 방안으로 현물환매입/선물환매도(buy/sell) 스왑을 이용한다. 이 경우 현물환매입 증가로 현물환율은 상승하고 선물환매도 증가로 선물환율은 하락하게 되어 스왑레이트가 낮아진다. 반대로 금융기관의 원화자금사정이 악화되면 원화차입을 위한 현물환매도/선물환매입(sell/buy) 스왑 증가로 스왑레이트가 올라간다. 한편 스왑레이 트가 내외금리차를 하회하면 외화차입 후 외환스왑(현물환매도/선물환매입)을 통해 원화를 조달한 다음 원화자산에 투자함으로써 환리스크 없이 이익을 획득할 수 있다. 이에 따라 ‘내외금리차-스왑레이트’를 차익거래 유인으로 해석할 수 있다.', related_words = ARRAY['금리평가이론']::text[] WHERE id = 332;  -- 스왑레이트
UPDATE public.words SET meaning = '스탠더드&푸어스는 무디스, 피치와 함께 세계 3대 국제신용평가기관으로 불리는 미국의 신용평가회사로서 1860년 Henry Varnum Poor가 설립한 Poor’s라는 투자정보서비스회사와', detailed_meaning = '스탠더드&푸어스는 무디스, 피치와 함께 세계 3대 국제신용평가기관으로 불리는 미국의 신용평가회사로서 1860년 Henry Varnum Poor가 설립한 Poor’s라는 투자정보서비스회사와 1916년 설립된 Standard의 두 회사가 1942년 합병하여 Standard&Poor’s로 출범하였다. 무디스와 마찬가지로 1929년 세계대공황을 계기로 높은 명성을 획득하여 성장하였는데 이 회사는 채권의 신용등급을 신용리스크에 따라 AAA(최우량)·AA(우량)·A(비교적우량)·BBB(중위)·BB(저중위)·B(저급)·CCC·CC·C(모두 최저급) 순으로 채권의 신용등급을 매기고 있으며 더불어 미국의 3대 주가지수인 S&P500지수도 발표하고 있다.스탠더드&푸어스는 각국의 정부채무에 대해 경제적, 재정적 성과 수치들을 합한 정량분석과 미래의 부채 지불 능력을 반영한 정성분석을 모두 실시하는 특징을 보이며 주요 신용평가 항목은 정치 리스크, 경제구조, 경제성장, 정부의 역할과 재정수지, 공공부채 부담, 물가안정, 경상수지 구조, 대외부채와 유동성 등이다.', related_words = ARRAY['무디스']::text[] WHERE id = 335;  -- 스탠더드&푸어스(S&P)
UPDATE public.words SET meaning = '스트레스 DSR이란 변동금리 대출 등을 이용하는 차주가 대출 이용기간 중 금리 상승으로 인해 원리금 상환 부담이 증가할 가능성을 감안하여 DSR 산정시 일정 수준의 가산금리 (스트레스 금리)를', detailed_meaning = '스트레스 DSR이란 변동금리 대출 등을 이용하는 차주가 대출 이용기간 중 금리 상승으로 인해 원리금 상환 부담이 증가할 가능성을 감안하여 DSR 산정시 일정 수준의 가산금리 (스트레스 금리)를 부과하여 대출한도를 산출하는 제도(실제 대출금리에는 미부과)를 말한다. 스트레스 DSR 제도는 금리변동 위험을 DSR에 정교히 반영하여 상환능력을 넘어서 는 과도한 가계대출 확대를 방지하고, 고정금리 확대 등 가계부채의 질적 개선을 도모하기 위해 도입되었다. 스트레스 DSR의 시행범위는 은행권 및 제2금융권의 모든 대출을 대상으로 한다. 다만 동 제도 도입으로 인해 차주들이 체감하는 대출한도 축소 부담이 과도 할 우려 등을 감안하여 2024년부터 3단계에 걸쳐 순차적·점진적으로 시행하였다. 스트레스 금리는 과거 5년 내 가장 높았던 수준의 가계대출 금리와 현 시점(매년 5월·11월 기준) 금리를 비교하여 결정하되 일정한 수준의 하한(1.5%), 상한(3.0%)을 부여한다. 스트레스 DSR 도입에 따라 DSR 산정시 스트레스 금리가 가산되면 차주별 대출한도가 줄어들어 가 계대출 수요를 억제하는 효과를 기대할 수 있다. 다만 스트레스 DSR 적용 과정에서 취약계층에 대한 신용공급이 제약될 우려가 있는 만큼 금융당국의 세심한 관리가 필요하다.', related_words = '{}'::text[] WHERE id = 338;  -- 스트레스 DSR
UPDATE public.words SET meaning = '예외적이지만 발생가능한(extreme but plausible) 위기 상황을 상정하여 개별 금융기관, 금융부문 및 금융시스템 전체의 취약성과 복원력을 평가하는 기법을 의미한다.', detailed_meaning = '예외적이지만 발생가능한(extreme but plausible) 위기 상황을 상정하여 개별 금융기관, 금융부문 및 금융시스템 전체의 취약성과 복원력을 평가하는 기법을 의미한다. 스트레스테스트(Stress Test)에서는 위기 시나리오 하에서 예상되는 금융기관의 손익, 자본비율, 현금흐름, 유동성 상황 등을 정량적으로 측정하여 리스크를 분석한다. 글로벌 금융위기를 계기로 개별 금융기관 단위보다는 금융시스템 전체 관점에서의 건전성 평가 및 규제 필요 성이 대두되면서 금융기관 간 연계성 및 거시-금융 연계성을 반영하는 거시 스트레스 테스트의 중요성이 높아지고 있다. 미국, EU 등 주요국 중앙은행 및 정책당국은 위기 이후거시 스트레스 테스트를 강화하고 이를 금융기관의 자본 규제 등 건전성정책 수행에도 활용하고 있다.', related_words = '{}'::text[] WHERE id = 339;  -- 스트레스 테스트(위기상황분석)
UPDATE public.words SET meaning = '금융시장의 금리, 주가, 환율 등의 변동에 따라 은행이 단기매매를 위해 트레이딩계정(trading book)에 보유한 금융상품의 가격이 하락하여 손실이 발생할 가능성을 의미한 다.', detailed_meaning = '금융시장의 금리, 주가, 환율 등의 변동에 따라 은행이 단기매매를 위해 트레이딩계정(trading book)에 보유한 금융상품의 가격이 하락하여 손실이 발생할 가능성을 의미한 다. 바젤은행감독위원회(BCBS)는 은행이 시장리스크에 상응하는 자기자본을 보유하도 록 의무화하고 있다. 글로벌 금융위기를 계기로 그 동안 시장리스크가 과소 평가되었다는 비판이 제기되면서 BCBS는 시장리스크에 대한 자본규제 체계 개선작업을 진행하였으며 2016년 1월 시장리스크에 대한 자본규제 개정 기준서를 공표하였다.', related_words = ARRAY['VaR(Value at Risk)']::text[] WHERE id = 343;  -- 시장리스크
UPDATE public.words SET meaning = '시장평균환율제도는 우리나라가 1990년 3월 국내 외환시장의 활성화와 자본 및 금융의 국제화를 촉진시키기 위한 환율제도의 단계적 개편방안의 일환으로 도입한 제도로서, 1997년 외환위기 이전까지', detailed_meaning = '시장평균환율제도는 우리나라가 1990년 3월 국내 외환시장의 활성화와 자본 및 금융의 국제화를 촉진시키기 위한 환율제도의 단계적 개편방안의 일환으로 도입한 제도로서, 1997년 외환위기 이전까지 시행되었다. 기본적으로 환율이 외환시장에서의 수요와 공급에 의해 결정되도록 하되, 급격한 환율 변동에 의한 외환시장 교란과 경제적 불안정을 완화하기 위하여 환율의 일중변동 폭을 제한하였다. 시장평균환율제도하에서는 외환중개회사를 통해 외국환은행 간 실제 거래된 환율을 거래량으로 가중평균하여 다음 영업일의 기준환율로 정하고, 동 기준환율을 중심으로 원/달러 환율이 상하 일정 범위 내에서만 변동되도록 하였다. 동 제도 도입 당시에는 일중 환율변동제한폭을 기준환율의 상하 0.4%로 설정하였으며 이후 변동제한폭을 지속적으로 확대하였는데, 1997년 11월 외환위기를 맞으면서 상하 10%로 대폭 확대하였다가 같은 해 12월 완전히 철폐하였고 이로 써 우리나라는 자유변동환율제도로 이행하였다.', related_words = ARRAY['고정환율제도/자유변동환율제도','미달러화페그제도']::text[] WHERE id = 345;  -- 시장평균환율제도
UPDATE public.words SET meaning = '시카고 연준의 금융상황지수(National Financial Conditions Index)는 미국의 금융시장 상황을 지수화하여 현재 금융시장이 긴축적인지 또는 완화적인지를 나타낸다.', detailed_meaning = '시카고 연준의 금융상황지수(National Financial Conditions Index)는 미국의 금융시장 상황을 지수화하여 현재 금융시장이 긴축적인지 또는 완화적인지를 나타낸다. 지수는 각종 신용스프레드, 채권발행량, 변동성 지수 등 신용(credit), 레버리지(leverage), 리스크(risk) 상황을 나타내는 105개의 금융변수로 구성된다. 지수는 0을 기준으로 음수일수록 금융여건이 완화적임을, 양수일수록 긴축적임을 나타내며, 절댓값이 커질수록 그정도가 심화됨을 의미한다. 시카고연준의 금융상황지수 외에도 Bloomberg, Goldman Sachs 등 여러 기관에서 금융상황지수를 산출하고 있다.', related_words = '{}'::text[] WHERE id = 346;  -- 시카고 연준 금융상황지수
UPDATE public.words SET meaning = '신용연계증권(Credit Linked Notes)은 지급보증계약과 유사한 신용파산스왑(CDS)을 증권화한 형태이다.', detailed_meaning = '신용연계증권(Credit Linked Notes)은 지급보증계약과 유사한 신용파산스왑(CDS)을 증권화한 형태이다. 신용연계증권의 보장매입자(CLN 매도자)는 기초자산의 신용상태와 연계된 증권을 발행하고 약정된 방식으로 이자를 지급하며, 보장매도자(CLN 매수자) 는 약정이자를 받는 대신 신용사건이 발생하는 경우 기초자산의 손실을 부담하게 된다. 신용연계증권 거래의 특징은 보장매도자가 지급하는 신용연계증권 매수대금이 신용사건발생시 보장매도자가 부담하게 되는 손실의 담보 역할을 한다는 점이다. 기초자산에 신용사건이 발생하는 경우 보장매입자는 수취한 신용연계증권 거래대금에서 기초자산의 손실분을 차감하여 보장매도자에게 돌려주거나, 기초자산을 보장매도자에게 인도한다. 이와 같이 신용연계증권은 신용파산스왑과는 달리 신용연계증권 거래대금이 담보 역할을 하고 있어 보장매도자의 신용도는 문제가 되지 않는다.', related_words = ARRAY['신용파생상품']::text[] WHERE id = 351;  -- 신용연계증권(CLN)
UPDATE public.words SET meaning = '바젤 자본규제에서는 신용위험을 채권·채무관계에서 채무자의 채무불이행, 이행거부 또는 신용도 하락 등으로 인해 발생하는 손실 가능성을 포괄하는 개념으로 정의한다.', detailed_meaning = '바젤 자본규제에서는 신용위험을 채권·채무관계에서 채무자의 채무불이행, 이행거부 또는 신용도 하락 등으로 인해 발생하는 손실 가능성을 포괄하는 개념으로 정의한다. 규제 ㅅ하에서 신용위험은 일정 기간(통상 1년) 이내에 발생할 수 있는 발생할 것으로 예상되는 부도율(PD; Probability of Default), 채무불이행이 발생했을 때 담보 등을 고려한 실제손실 비율(LGD; Loss Given Default), 부도 시 익스포저(EAD; Exposure At Default) 등의 지표를 통해 체계적으로 산출하되 예상을 벗어나는 충격적 손실(예상외 손실, UL; Unexpected Loss)도 신용위험에 포함한다.', related_words = ARRAY['예상손실']::text[] WHERE id = 352;  -- 신용위험(신용리스크)
UPDATE public.words SET meaning = '신용창조(Credit Creation)는 일반적으로 은행이 예금과 대출업무를 반복적으로 취급하는 과정에서 예금통화를 만들어내는 현상을 말한다.', detailed_meaning = '신용창조(Credit Creation)는 일반적으로 은행이 예금과 대출업무를 반복적으로 취급하는 과정에서 예금통화를 만들어내는 현상을 말한다. 예를 들어 중앙은행이 A은행에 100만큼의 본원통화를 공급하면 A은행은 이중 10(지급준비율 10%, 민간의 화폐보유성향 0% 가정)을 지급준비금으로 남겨두고 나머지 90을 대출로 운용한다. 대출받은 사람이 이를 B은행에 예금을 하면 B은행은 다시 이 가운데 9를 지급준비금으로 남겨두고 나 머지 81을 다시 대출하게 된다. 이러한 과정이 무한정 반복되면 결국 예금은 1,000(그러나 대출받는 사람이 전부 예금하기 보다는 이중 일부를 현금으로 보유하게 되는데 그러면 동 현금 부분은 신용창조 사이클에서 누락되므로 실제통화량은 1,000 보다 작아진다) 만큼 늘어난다. 즉, 100이라는 본원통화가 신용창조를 통해 1,000이라는 예금통화가 창출되었다. 본원통화와 통화량 사이의 관계를 통화승수라 하는데 여기서 통화승수는 10이 다(1000÷100). 지급준비율을 변경하면 승수효과를 통해 신용창출효과(통화량)에 영향을 주기 때문에 지급준비제도는 중앙은행의 핵심적인 유동성조절 수단이다. 지급준비율을 인하하면 통화승수가 커지기 때문에 통화량이 늘어나고 반대로 지급준비율을 인상하면 통화승수가 줄어들기 때문에 통화량이 감소한다. 그래서 중앙은행은 통화완화가 필요 한 경우에는 지급준비율 인하를 통해, 통화긴축이 필요한 경우에는 지급준비율 인상을 통해 통화량을 조절하게 된다.', related_words = ARRAY['지급준비제도','통화승수','본원통화']::text[] WHERE id = 353;  -- 신용창조
UPDATE public.words SET meaning = '신용파생상품(Credit Derivative)이란 채권, 대출금 등과 같이 차입자 또는 발행자의 신용에 따라 가치가 변동하는 기초자산(underlying asset)의 신용위험(credit', detailed_meaning = '신용파생상품(Credit Derivative)이란 채권, 대출금 등과 같이 차입자 또는 발행자의 신용에 따라 가치가 변동하는 기초자산(underlying asset)의 신용위험(credit risk)을 분리하여 이를 다른 거래상대방에게 이전하고 그 대가로 프리미엄(수수료)을 지급하는 금융상품을 말한다. 금리, 환율 등 가격변수의 변동에 따라 가치가 변동하는 금융자산의 시장위험(market risk)을 선도 및 선물거래, 스왑, 옵션 등을 통해 관리할 수 있는데, 차입자의 부도, 신용등급 변동 등에 따라 자산가치가 등락하는 금융자산의 신용위험은 신용파생상품의 거래를 통해 그 위험을 헤지할 수 있다. 신용파생상품 거래에서 신용위험을 전가 하고 수수료를 지급하는 거래자는 보장매입자(protection buyer), 신용위험을 매수하고 그 대가로 수수료를 수취하는 거래자는 보장매도자(protection seller)라고 한다. 보장매입자는 보유채권의 신용위험 노출을 없애고 기존 포트폴리오의 만기 구조를 개선할 수 있으며, 보장매도자는 수수료 수입을 통해 수익증대를 도모하고 투자수단을 다양화할 수 있다. 일반적으로 신용파생상품은 기초자산의 이전 없이 신용위험만을 분리하여 거래하므로 신용위험에 대한 가격산정의 적정성을 높여 신용위험을 다수의 투자자에 분산시키는 기능을 수행한다.', related_words = ARRAY['신용위험(신용리스크)','시장리스크']::text[] WHERE id = 354;  -- 신용파생상품
UPDATE public.words SET meaning = 'BIS 자기자본비율 계산시 난내자산의 경우 익스포저에 거래상대방의 신용위험도에 따른위험가중치를 곱하여 위험가중자산(risk-weighted assets)을 산출하게 된다.', detailed_meaning = 'BIS 자기자본비율 계산시 난내자산의 경우 익스포저에 거래상대방의 신용위험도에 따른위험가중치를 곱하여 위험가중자산(risk-weighted assets)을 산출하게 된다. 난외자산의 경우 관련 권리·의무가 미확정된 상태로 난내자산으로 전환되기 전까지는 익스포저를 산출할 수 없으므로 난외자산 계약의 명목원금에 신용환산율(Credit Conversion Factor) 을 곱해서 산출된 신용리스크 상당액을 익스포저로 보고 이에 거래상대방에 따른 위험 가 중치를 곱하여 위험가중자산을 구한다. 따라서 신용환산율은 난외자산이 실제로 활용되어 난내자산으로 전환될 확률 개념이며, 특별한 원칙에 따라 결정되기 보다는 거래 유형및 과거 경험을 토대로 바젤위원회(BCBS)가 산정한 비율을 사용하고 있다.', related_words = ARRAY['BIS 자기자본비율']::text[] WHERE id = 356;  -- 신용환산율
UPDATE public.words SET meaning = '신주인수권부사채(Bond with Warrant)는 채권을 발행한 회사가 주식을 발행할 경우 투자자가 미리 약정된 가격에 일정한 수량의 신주(新株)를 인수할 수 있는 권리인 워런트', detailed_meaning = '신주인수권부사채(Bond with Warrant)는 채권을 발행한 회사가 주식을 발행할 경우 투자자가 미리 약정된 가격에 일정한 수량의 신주(新株)를 인수할 수 있는 권리인 워런트 (Warrant)가 결합된 회사채를 말한다. 투자자들은 발행기업의 주가가 약정된 매입가를 상회하면 신주를 인수하여 차익을 얻을 수 있고, 그렇지 않으면 인수권을 포기하면 된다. BW는 일반 채권에 비해 발행금리가 낮아 발행 회사는 적은 비용으로 자금을 조달할 수있는 장점이 있다. 또한 발행기업의 주가가 약정된 매입가를 상회할 경우에는 투자자들의 신주인수권 행사에 힘입어 자기자본이 증가하면서 새로운 자금조달이 가능하게 된다. 이 경우 투자자는 채권으로부터 이자수익을, 주식으로부터 주가 상승에 따른 자본수익을 기대할 수 있어 투자의 안전성과 수익성 모두를 확보하게 된다. BW는 발행회사의 주식으로 전환할 수 있는 권리가 부여된 전환사채(CB; Convertible Bond)와 비슷한 것처럼 보이 지만, CB는 전환 시 그 사채가 소멸되는 데 반해, BW는 신주인수권 행사 시 인수권 부분만 소멸될 뿐 사채 부분은 계속 효력을 갖게 되므로 양자 간에는 차이가 있다.', related_words = ARRAY['전환사채(CB)']::text[] WHERE id = 357;  -- 신주인수권부사채(BW)
UPDATE public.words SET meaning = 'EMBI+(Emerging Market Bond Index+)는 신흥국(이머징 마켓) 정부가 국제금융시장 ㅅ에서 발행한 달러화 표시 국채의 수익률을 기반으로 하는 대표적인 벤치마크 지수로 글로 벌', detailed_meaning = 'EMBI+(Emerging Market Bond Index+)는 신흥국(이머징 마켓) 정부가 국제금융시장 ㅅ에서 발행한 달러화 표시 국채의 수익률을 기반으로 하는 대표적인 벤치마크 지수로 글로 벌 투자은행인 JP Morgan이 산출한다. 구체적으로는 신흥시장국 채권 등의 가산금리를 거래금액을 기준으로 가중평균하여 지수화한다. 미국, 유럽, 일본 등 신용등급이 높은 국가에서 발행한 채권에 주로 투자하는 펀드를 글로벌 채권펀드, BRICs 등 신흥시장 국가 에서 발행한 채권에 주로 투자하는 펀드를 신흥시장국 채권펀드라고 하는데, 양자간 투자위험도의 차이 때문에 통상 후자의 금리(투자수익률)는 전자의 금리보다 높다. EMBI+ 수익률에서 미국 국채수익률을 차감한 값을 EMBI+ 스프레드라고 하며, 일반적으로 신흥국의 위험이 증가하면 동 스프레드가 커진다.', related_words = ARRAY['MSCI 지수','FTSE 지수']::text[] WHERE id = 358;  -- 신흥시장국채권지수(EMBI+)
UPDATE public.words SET meaning = '구직단념자라고도 하며, 비경제활동인구 중 잠재구직자의 일부분이며 취업 희망과 취업가능성 기준 외에도 노동시장적 사유로 지난 4주간 구직활동을 하지 않는 자 중 지난 1년내 구직 경험이 있는 사람을', detailed_meaning = '구직단념자라고도 하며, 비경제활동인구 중 잠재구직자의 일부분이며 취업 희망과 취업가능성 기준 외에도 노동시장적 사유로 지난 4주간 구직활동을 하지 않는 자 중 지난 1년내 구직 경험이 있는 사람을 의미한다. 여기서 노동시장적 사유라 함은 다음과 같은 사유로 구직활동을 하지 않게 된 경우를 의미한다. ① 전공, 경력, 임금수준, 근로조건 등의 면에서 적당한 일자리가 없을 것 같아서 ② 지난 4주간 이전에 구직하여 보았지만 일자리를 찾을 수 없어서 ③ 교육·기술·경험 부족 등의 면에서 자격이 부족하여 지난 4주간 구직활동을 하지 않은 경우를 의미한다.', related_words = ARRAY['고용보조지표','자발적 실업']::text[] WHERE id = 359;  -- 실망실업자
UPDATE public.words SET meaning = '실업률과 자연실업률간의 차이를 말한다.', detailed_meaning = '실업률과 자연실업률간의 차이를 말한다. 실업률갭은 노동시장의 여력(slack)을 평가할수 있는 유용한 지표로, 잠재GDP와 실제GDP의 차이인 GDP갭과 함께 경기수준 또는 경제 전반의 유휴자원을 파악할 때 유용하다. 실업률갭이 양(+)인 경우에는 노동공급 여력이 양호한 상황으로 인플레이션압력이 높지 않음을 나타내며, 실업률갭이 음(-)인 경우에는 노동공급 여력이 소진된 상황으로 노동력 확보 경쟁 등으로 인한 임금상승이 인플레이션압력을 높일 가능성이 큰 상황으로 볼 수 있다. 따라서 물가안정을 주된 정책목표로 하는 중앙은행의 경우 실업률갭은 노동시장을 통한 인플레이션 상승압력을 평가하거나, 통화정책 기조가 노동시장 수급불균형 해소에 어느 정도 부합하는지 등을 살펴보는 데 유용하게 활용할 수 있다. 다만 중앙은행이 실업률갭만을 염두에 두고 통화정책을 운영하는 데는 한계가 있는데, 이는 실업률갭의 구성요소인 자연실업률이 실시간으로 관측되지 않고 추정방법도 다양하여 정확한 추정이 이루어지지 않을 경우 중앙은행이 원하는 정책효과를 얻지 못할 수 있기 때문이다.', related_words = ARRAY['제조업평균가동률갭','자연실업률']::text[] WHERE id = 362;  -- 실업률갭
UPDATE public.words SET meaning = '근로자가 노동의 대가로 받는 임금을 현재의 화폐단위로 표시한 것을 명목임금이라고 하는데 이러한 명목임금으로 재화와 서비스를 실제 구입할 수 있는 수량 즉, 구매력을 측정하기 위해 명목임금을', detailed_meaning = '근로자가 노동의 대가로 받는 임금을 현재의 화폐단위로 표시한 것을 명목임금이라고 하는데 이러한 명목임금으로 재화와 서비스를 실제 구입할 수 있는 수량 즉, 구매력을 측정하기 위해 명목임금을 소비자물가지수로 나눈 것을 실질임금이라고 한다. 물가상승률이 명목상승률보다 더 높으면 실질임금은 오히려 줄어들어 실제 구매력은 감소하게 된다.', related_words = ARRAY['소비자물가지수(CPI)','인플레이션']::text[] WHERE id = 364;  -- 실질임금
UPDATE public.words SET meaning = '환율은 양 통화 간의 교환비율이기 때문에 주요 교역상대국 통화 전체에 대한 자국 통화가치의 변동을 파악하는 데에는 부족한 측면이 있다.', detailed_meaning = '환율은 양 통화 간의 교환비율이기 때문에 주요 교역상대국 통화 전체에 대한 자국 통화가치의 변동을 파악하는 데에는 부족한 측면이 있다. 실효환율(Effective Exchange Rate) 은 이러한 점을 고려해 자국통화와 주요 교역상대국 통화 간의 환율을 무역 비중으로 가중평균하여 산출한 환율로서 자국 상품의 종합적인 가격경쟁력 지표로 볼 수 있다. 한 편, 일국 통화의 대외가치는 환율 변동뿐 아니라 국가 간의 물가상승률의 차이에 의해서 도 영향을 받게 되는 바, 국가 간의 물가변동을 고려하지 않고 주요 교역대상국의 환율 변동만을 종합적으로 고려한 실효환율을 명목실효환율(nominal effective exchange rate) 이라고 하고 물가변동까지를 고려한 실효환율을 실질실효환율(real effective exchange rate)이라고 한다. 명목실효환율이나 실질실효환율은 명목환율의 절대적 수준이 통화별로 상이한 점 때문에 절대적 환율 수치가 아닌 기준년 대비 지수 형태로 표시되는 경우가 많은데 이를 각각 명목실효환율지수 또는 실질실효환율지수라고 한다. 지수가 상승하면자국 통화가 고평가되어 수출 가격경쟁력이 약화되고, 하락하면 저평가되어 수출 가격경쟁력이 강화됨을 의미한다.', related_words = '{}'::text[] WHERE id = 365;  -- 실효환율
UPDATE public.words SET meaning = '국민경제의 최종수요는 크게 소비·투자 중심의 내수(국내경제 순환)와 수출 중심의 외수로 구분할 수 있다.', detailed_meaning = '국민경제의 최종수요는 크게 소비·투자 중심의 내수(국내경제 순환)와 수출 중심의 외수로 구분할 수 있다. 세계화된 국민경제는 일반적으로 내수와 외수의 두 개의 축이 조화롭게 떠받칠 때 지속 성장이 가능하게 된다. 쌍순환(雙循環) 전략은 2020년 이후 미국과 중국의 무역 갈등이 심화되면서 중국 정부가 제시하고 사용한 용어이다. 안정적이고 자립적인 경제시스템을 구축하기 위해 기술 혁신을 통한 투자 확대와 소비확충의 내순환을 바탕으로 수출 증대(외순환)를 도모하겠다는 의미를 담고 있다. 우리나라도 수출 비중이 높아글로벌 경제와의 연계가 매우 중요하다. 그래서 안정적이고 지속적인 성장을 위해 내수와 수출의 보완과 조화로운 확대를 추구하여왔다. 소비 중심의 내수가 건전하고 단단해야 글로벌 충격에 잘 견딜 수 있으며 다른 나라와의 관계 유지 등을 통해 무역을 확대하여 국민경제의 성장을 추구할 수 있는 것이다.', related_words = ARRAY['국민소득']::text[] WHERE id = 366;  -- 쌍순환 전략
UPDATE public.words SET meaning = 'AMRO(ASEAN+3 Macroeconomic Research Office)는 아세안(ASEAN) 10개국과 한국, 중국, 일본 등 13개국이 치앙마이 이니셔티브 다자화 협정(CMIM;', detailed_meaning = 'AMRO(ASEAN+3 Macroeconomic Research Office)는 아세안(ASEAN) 10개국과 한국, 중국, 일본 등 13개국이 치앙마이 이니셔티브 다자화 협정(CMIM; Chiang Mai Initiative Multilateralization)의 효과적인 운영을 지원하기 위하여 2011년에 설립한 기구로서 싱가포르에 본부를 두고 있다. 설립 당시에는 싱가포르 민간법인의 형태였으나 원활한 역내 협력 및 감시업무 수행을 위하여 2013년 5월 국제기구화하기로 합의하고 이후 2016년 2월 AMRO 협정문이 발효됨에 따라 국제기구로 공식 전환되었다. 이에 따라 CMIM, AMRO로 구성되는 역내 금융안정망의 위상이 크게 높아졌으며 국제통화기금(IMF) 등 여타 국제기구와 공식적으로 협력할 수 있게 되는 등 AMRO의 역량도 강화되었다. AMRO는 ASEAN+3 지역의 거시경제 연구와 금융감시를 전담하는 기구로서, 평시와 위기 시에 따라 차별화된 역할을 수행한다. 평시에는 역내 전체 및 회원국별 거시경제 동향과 전망을 분석해 보고서를 작성하고, ERPD 회의에서 관련 자료를 제공한다. 또한 회원국과의 연례협의를 통해 국가별 감시보고서 (Annual Consultation Report)를 제출하며, 지역경제전망보고서(AERO), 금융안정보고서(AFSR), 재정정책보고서(AFPR) 등 정기간행물을 발간한다. 위기 시에는 지원대상국의 거시경제 상황을 심층 분석하고 정책 권고안을 제시하여 CMIM 의사결정기구의 판단을 지원하며, 동시에 CMIM 협정상 인출 조건 준수 여부를 점검·감시하는 기능을 수행한다.', related_words = ARRAY['‌동남아시아국가연합(ASEAN)','동남아시아국가연합+한·중·일(ASEAN+3)']::text[] WHERE id = 367;  -- 아세안+3 거시경제조사기구(AMRO)
UPDATE public.words SET meaning = '양적완화정책(QE; Quantitative Easing)이란 금리중시 통화정책을 시행하는 중앙은행이 정책금리가 제로 수준에 근접하게 인하(추가적인 정책금리 인하 여지가 없음)하였음에도 불구하고', detailed_meaning = '양적완화정책(QE; Quantitative Easing)이란 금리중시 통화정책을 시행하는 중앙은행이 정책금리가 제로 수준에 근접하게 인하(추가적인 정책금리 인하 여지가 없음)하였음에도 불구하고 경제 회복이 당초의 기대에 미치지 못함에 따라 장기금리 하락을 유도하기 위해국채 등을 무제한으로 매입하여 유동성을 충분히 공급함으로써 중앙은행의 대차대조표를 확대하는 정책을 말한다. 이러한 양적완화정책은 2001년 3월 일본은행이 제로금리 하에 서 일본은행 당좌예금잔액을 확대하는 정책을 도입하면서 처음으로 사용되었다. 2008년9월 글로벌 금융위기가 실물부문으로 빠르게 확산하면서 주요 선진국의 경기침체가 심화되자 주요국 중앙은행은 전통적 통화정책의 한계에 봉착하게 되었고, 이러한 상황을 타개하기 위해 비전통적 통화정책 수단인 양적완화정책을 실시하게 되었다. 양적완화는 통화정책의 완화기조가 상당 기간 유지될 것이라는 신호를 줌으로써 민간 경제주체들의 향후경기회복에 대한 기대를 높이거나, 금융시장 유동성 사정 개선 및 위험회피 심리 완화로 금융기관 대출이 늘어나는 등의 경로를 통해 금융시장 및 실물경제에 영향을 미치게 된 다. 하지만 양적완화가 장기간 지속될 경우에는 민간 경제주체들의 과도한 수익 추구 행위 등으로 금융불균형이 심화되는 부작용이 발생할 가능성이 있다. 한편 중앙은행이 양적완화정책으로 크게 늘어난 보유자산 규모를 경기회복세 등을 배경으로 점진적으로 축소할 때 그 속도가 경기회복세에 비하여 더딜 경우에는 과잉 유동성이 자칫 물가상승압력으로 작용할 가능성도 배제할 수 없다. 한편 양적완화정책과 대비되는 개념으로 질적완화 정책(Qualitative Easing)이 있다. 이것은 중앙은행의 대차대조표는 확대하지 않으면서 중앙은행의 자산구성을 변경하는 것이다. 즉, 중앙은행은 대부분 무위험자산인 국채를 보유하고 있는데 이 중 일부를 신용위험이 있는 채권으로 포트폴리오를 조정(중앙은행이 금융시장에서 신용위험채권을 매입함을 의미)함으로써 금융시장의 신용경색을 타개하고 자 하는 정책수단이다.', related_words = ARRAY['출구전략']::text[] WHERE id = 373;  -- 양적완화정책
UPDATE public.words SET meaning = '어음교환이란 다수의 은행이 일정한 시간에 특정 장소에 모여 자행이 수납한 어음(수표및 제 증서 포함) 중 다른 은행을 지급지로 하는 어음과 다른 은행이 수납한 어음 중 자행을 지급지로 하는 어음을', detailed_meaning = '어음교환이란 다수의 은행이 일정한 시간에 특정 장소에 모여 자행이 수납한 어음(수표및 제 증서 포함) 중 다른 은행을 지급지로 하는 어음과 다른 은행이 수납한 어음 중 자행을 지급지로 하는 어음을 서로 교환하고, 이에 따른 대금을 청산하는 것을 말하며 어음교환이 이루어지는 장소를 어음교환소라 한다. 어음교환제도는 어음·수표의 추심에 따른은행 업무부담 및 비용을 절감하고 추심 소요기간을 단축시키는 효과가 있다. 우리나라의 어음교환소는 1910년 7월 서울에 설립된 사설 경성어음교환소(현 서울어음교환소)가 그 효시로 이후 인천, 부산, 대구, 광주, 대전 등 경제규모가 큰 대도시로 설치지역이 확대되었다. 이후에도 경제규모의 확대와 더불어 어음교환소 설치가 확대되어 2000년대에는 전국적으로 약 50여개의 어음교환소가 운영되었다. 그러나 2010년 11월 어음교환정보를 전자적인 방식으로 교환 처리하는 전자정보교환제도(truncation)가 전국으로 확대 실시되면서 지방어음교환소는 모두 폐쇄되었으며 현재는 서울어음교환소에서 모든 업무를 처리하고 있다.', related_words = ARRAY['소액지급시스템','전자어음']::text[] WHERE id = 375;  -- 어음교환
UPDATE public.words SET meaning = '에너지 믹스(Energy Mix)는 인구 증가와 전력사용량의 급증에 대응하여 에너지를 다양한 방법으로 생산하는 것을 의미한다.', detailed_meaning = '에너지 믹스(Energy Mix)는 인구 증가와 전력사용량의 급증에 대응하여 에너지를 다양한 방법으로 생산하는 것을 의미한다. 국가나 지역이 사용하는 전체 에너지 소비에서 원자력, 화력, 재생에너지 등 서로 다른 에너지원이 차지하는 비율을 뜻하는 개념이다. 정부는 에너지 생산의 경제성과 환경에 미치는 영향, 에너지 안보 등을 고려하여 적합한 에너지믹스를 목표로 설정하고 이를 달성하기 위한 정책을 추진한다. 에너지 수요가 급증하면서 하나의 에너지원만으로 그 수요를 충족시키기 어려워 에너지원을 조합하는 에너지믹스가 중요해졌다. 또한 산업혁명 이후 크게 늘어난 화석연료 사용으로 기후위기 이슈가 나타나 면서 에너지믹스가 더욱 관심을 받게 되었다. 최근 탄소중립 목표 달성을 위해 석탄, 석유등의 이산화탄소를 배출하는 연료를 줄이고 신재생에너지 비중을 확대하는 방향으로 에 너지믹스를 조정하는 추세에 있다.', related_words = ARRAY['탄소배출권']::text[] WHERE id = 377;  -- 에너지 믹스
UPDATE public.words SET meaning = '역모기지론(Reverse Mortgage Loan)은 주택을 소유하고 있으나 자체수입이 부족한 고 령자가 보유주택을 담보로 소유자 및 배우자의 사망 시까지 노후생활에 필요한 자금을 연금 형태로', detailed_meaning = '역모기지론(Reverse Mortgage Loan)은 주택을 소유하고 있으나 자체수입이 부족한 고 령자가 보유주택을 담보로 소유자 및 배우자의 사망 시까지 노후생활에 필요한 자금을 연금 형태로 받아 안정된 주거생활을 확보하는 제도이다. 역모기지론을 활용하는 경우, 고 령자들은 보유주택의 유동화를 통해 현 주거지에서 일정 수준의 생활을 유지하고, 대출금융기관은 고령자가 사망한 이후 동 담보주택을 처분하여 대출 원리금을 회수하게 된다. 역모기지론은 고령자가 자식이나 주위의 도움 없이 스스로 경제적 문제를 해결하는 방안이 될 수 있다. 또한, 사회 전체적인 측면에서도 적은 규모의 재정 지원으로 고령층의 복지문제를 해결할 수 있어 저비용·고효율의 예산 운용도 기대할 수 있다. 역모기지론은 주택을 담보로 한 장기대출이라는 점에서 모기지론과 유사하다. 그러나 역모기지론은 고령자의 생계비 조달이 목적이고, 모기지론은 주택구입이 목적이므로 대출목적, 이용자 등에 서 모기지론과 차이가 있다. 또한, 모기지론은 주택구입자가 대출금의 일정 부분을 매월상환하므로 기간 경과에 따라 부채가 감소하고 주택의 순자산 가치는 증가하는 반면, 역모기지는 매달 약정금액을 지급받으므로 기간 경과에 따라 부채가 증가하고 주택의 순자산 가치는 감소하게 된다.', related_words = ARRAY['모기지대출']::text[] WHERE id = 380;  -- 역모기지론
UPDATE public.words SET meaning = '펀드는 근거 법률에 따라 역외펀드(Off-Shore Fund)와 역내펀드(On-Shore Fund)로 구분되는데 역외펀드는 외국의 법률에 의하여 외국에서 설정, 설립된 것으로 외국펀드라고 도 한다.', detailed_meaning = '펀드는 근거 법률에 따라 역외펀드(Off-Shore Fund)와 역내펀드(On-Shore Fund)로 구분되는데 역외펀드는 외국의 법률에 의하여 외국에서 설정, 설립된 것으로 외국펀드라고 도 한다. 역내펀드는 국내 법률에 의하여 국내에서 설정, 설립된 것으로 국내 자산에 주로 투자하는 국내투자펀드, 해외 자산에 주로 투자하는 해외투자펀드로 구분된다. 역외펀드는 국외에서 설정되어 운용되므로 세금이나 규제 등에서 국내법의 적용을 받지 않지만, 해외펀드는 국내법의 적용을 받는다는 점에서 차이가 있다. 한편 역외펀드는 기업 및 금융회사의 유가증권 매매차익에 대한 과세가 없거나 과세가 상대적으로 적은 지역, 또는 외국환관리가 엄격하지 않은 지역에 이름뿐인 회사(페이퍼 컴퍼니)를 설립하고, 실질적인영업은 본토에서 행하는 경우가 일반적이다. 대서양 연안의 더블린, 유럽의 작은 도시국가 룩셈부르크, 동남아의 홍콩, 싱가포르, 라부안, 아메리카 대륙 연안의 바하마, 버뮤다 제도, 케이먼군도 등이 주요 역외펀드의 거점 역할을 하고 있다.', related_words = '{}'::text[] WHERE id = 381;  -- 역외펀드
UPDATE public.words SET meaning = '연방준비제도(FRS; Federal Reserve System)는 1907년 금융공황 후 그 대책으로서 1913년에 제정된 연방준비법(Federal Reserve Act)에 의해서 창설된 미국', detailed_meaning = '연방준비제도(FRS; Federal Reserve System)는 1907년 금융공황 후 그 대책으로서 1913년에 제정된 연방준비법(Federal Reserve Act)에 의해서 창설된 미국 특유의 중앙은행제도이다. 동 제도는 연방준비제도이사회(Board of Governors)와 연방공개시장위원회(Federal Open Market Committee)를 정점으로 이들을 지원하는 본부와 12개 지역 연방준비은행(FRB; Federal Reserve Bank)으로 구성되어 있다. 연방준비제도이사회는 상원의 승인을 얻어 대통령이 임명하는 7인의 전임이사로 구성되며, 통화정책을 수립하고 지역 연방준비은행을 통할하는 최고 의사결정기구이다. 연방공개시장위원회는 공개시장운영정책을 수립·집행하는 기구이며, 연방준비은행에 대해서 지정한 공개시장운영의 실시를 명할 수 있다. 한편, 지역 연방준비은행은 12개 지역의 중앙은행 역할을 하며, 금융기관 지급준비금관리, 재할인, 지급결제, 연방준비권의 발행, 가맹 주립은행에 대한 업무감독, 국고대리업무 등 연방준비제도의 일상적인 업무를 수행한다.', related_words = ARRAY['중앙은행']::text[] WHERE id = 383;  -- 연방준비제도(FRS)/ 연방준비은행(FRB)
UPDATE public.words SET meaning = '연차보고서는 한국은행이 발간하는 법정 보고서이며 1년간의 경제 동향, 통화신용정책운용 내용, 금융시장 안정 조치, 국제 협력 활동, 조사·연구 결과 등을 종합적으로 정리한 자료이다.', detailed_meaning = '연차보고서는 한국은행이 발간하는 법정 보고서이며 1년간의 경제 동향, 통화신용정책운용 내용, 금융시장 안정 조치, 국제 협력 활동, 조사·연구 결과 등을 종합적으로 정리한 자료이다. 이는 한국은행법 제102조에 따라 매년 국회에 보고되며, 국민과 시장 참가자에 게 주요 경제 상황과 정책 방향을 투명하게 전달하는 주요 커뮤니케이션 수단 중 하나이다. 주요 내용으로는 ▲기준금리 결정과 경기 및 물가 흐름, ▲유동성 공급 및 금융안정 방안, ▲국내외 경제 환경 분석, ▲화폐 발행 및 지급결제제도 운영, ▲기후변화, 고령화 등 구조적 이슈에 대한 연구 결과, ▲국제 금융기구와의 협력 내용 등이 포함된다. 연차보고서는 단순한 실적 보고서를 넘어, 통화당국의 경제 인식과 정책 철학을 담은 자료로 해석되며, 경제 연구자·정책 입안자·투자자에게 폭넓게 활용된다. 동 보고서는 한국은행 홈페이지에 등록되어 누구나 열람할 수 있다.', related_words = '{}'::text[] WHERE id = 385;  -- 연차보고서
UPDATE public.words SET meaning = '예금보험은 금융기관의 예금지급정지, 파산 등으로 해당 금융기관이 기존 예금자의 예금인출요구에 응할 수 없는 경우 예금보험기관이 당해 금융기관을 대신하여 예금을 지급함 으로써 예금자를 보호하고,', detailed_meaning = '예금보험은 금융기관의 예금지급정지, 파산 등으로 해당 금융기관이 기존 예금자의 예금인출요구에 응할 수 없는 경우 예금보험기관이 당해 금융기관을 대신하여 예금을 지급함 으로써 예금자를 보호하고, 대규모 예금인출사태(뱅크런)를 방지하여 금융안정을 유지하도록 하는 공적보험이다. 보험가입금융기관은 이러한 서비스의 대가로 일정한 보험료를 정기적으로 예금보험기관에 납부하여야 한다. 일반적으로 예금자를 보호하는 수단으로 금융기관 감독제도, 지급준비금제도 및 상호보장제도 등이 있으나 예금보험제도는 여타감독 수단보다도 가장 직접적으로 예금자를 보호하는 수단으로서 금융제도의 안정성 유지를 위해 다수 국가에서 시행하고 있다. 우리나라에서는 일부 금융업권에서 개별적으로 기금을 조성하여 예금보험제도를 운영하다가, 1996년 6월 ‘예금자 보호법’이 시행되면서 예금보험공사가 예금보험업무를 전담하고 있다. 예금보험의 적용대상기관은 은행, 투자매매업자, 투자중개업자, 증권금융회사, 보험회사, 종합금융회사, 상호저축은행 및 상호저축은행중앙회이며, 예금, 적금, 부금, 수입보험료 및 확정기여형퇴직연금 적립금 등을 적용대상예금으로 한다. 동일한 금융회사 내에서 예금자 1인이 보호받을 수 있는 한도(원금과 소정의 이자 합산)는 예금보험공사 설립 당시 2,000만 원이었다. 이후 1997년 11월에는 예금 전액으로 확대되기도 하였으나, 2001년 1월부터 5,000만 원으로 운용되었다 가 2025년 9월 1일부터 1억 원으로 상향되었다.', related_words = ARRAY['뱅크런','지급준비제도']::text[] WHERE id = 388;  -- 예금보험제도
UPDATE public.words SET meaning = '예금취급기관이란 고객으로부터 예금을 수취하고 이를 기반으로 대출 등 금융중개 기능을 수행하며, 통화창출 기능을 갖는 금융기관을 말한다.', detailed_meaning = '예금취급기관이란 고객으로부터 예금을 수취하고 이를 기반으로 대출 등 금융중개 기능을 수행하며, 통화창출 기능을 갖는 금융기관을 말한다. 일반적으로는 은행법에 따른 은 행(시중은행, 지방은행, 인터넷전문은행 등)과 비은행 예금취급기관(상호저축은행, 신용협동조합, 새마을금고, 농·수·산림조합의 상호금융, 우체국예금계정 등)이 이에 해당한 다. 또한 산업은행, 중소기업은행, 농협은행, 수협은행 등 일부 특수은행도 예금취급기관으로 분류된다. 다만, 예금취급기관의 범위는 정의의 목적에 따라 달라질 수 있다. 예를 들어, 한국은행이 통화지표 등 거시경제 통계를 작성할 때는 금융자산의 중개 및 운용기능을 기준으로 하여 한국은행(중앙은행), 한국수출입은행, 자산운용회사, 신탁회사 등 도 예금기관에 포함시키는 경우가 있다. 이는 예금 수취 여부보다는 금융시장에서의 자금흐름과 통화창출에 기여하는 기능적 역할을 기준으로 한 분류이다. 반면, 실무적·소비자중심의 정의에서는 일반 개인이나 기업이 예금을 맡기고 대출을 받을 수 있는 기관을 의 미하므로, 한국은행, 수출입은행, 자산운용회사, 신탁회사 등은 예금취급기관에서 제외된 다. 특히 한국은행은 중앙은행으로서 통화정책과 지급결제 시스템을 운영하지만 일반 고 객의 예금 수취 기능은 없으며, 수출입은행은 정책금융기관으로서 일반적인 예금 수취 기능을 수행하지 않는다.', related_words = ARRAY['중앙은행']::text[] WHERE id = 389;  -- 예금취급기관
UPDATE public.words SET meaning = '실시간 총액결제시스템에서는 금융기관의 자금이체 지급지시가 접수되는 즉시 처리되는 것을 원칙으로 하나, 미래의 특정시점에서 자금결제가 이루어지도록 시스템이 금융기관으로부터 미리 자금이체신청을 받아', detailed_meaning = '실시간 총액결제시스템에서는 금융기관의 자금이체 지급지시가 접수되는 즉시 처리되는 것을 원칙으로 하나, 미래의 특정시점에서 자금결제가 이루어지도록 시스템이 금융기관으로부터 미리 자금이체신청을 받아 두었다가 결제시점이 도래하면 자동으로 결제하도 록 하는 제도를 예약자금이체제도라 한다. 한은금융망에서는 두 가지 종류의 예약자금이 체제도를 운영하고 있다. 하나는 지정시점에 금융기관 간 차액결제가 원활히 이루어질 수있도록 결제자금이 부족한 금융기관이 다른 금융기관으로부터 자금을 차액결제시점에서 수취할 수 있는 지정시점 예약자금이체제도이고, 다른 하나는 금융기관이 지정하는 특정시점에 자금을 이체하는 일반 예약자금이체제도이다.', related_words = ARRAY['일중당좌대출제도']::text[] WHERE id = 394;  -- 예약자금이체제도
UPDATE public.words SET meaning = '오픈뱅킹(Open Banking)이란 금융기관이 보유한 고객의 금융 데이터를 고객의 동의를 받아 API(Application Programming Interface)를 통해 제3자 금융 서비스', detailed_meaning = '오픈뱅킹(Open Banking)이란 금융기관이 보유한 고객의 금융 데이터를 고객의 동의를 받아 API(Application Programming Interface)를 통해 제3자 금융 서비스 제공자에게개방하고 이를 기반으로 고객이 다양한 금융 서비스를 더욱 편리하게 이용할 수 있도록허용하는 제도이다. 오픈뱅킹이 이루어질 경우 고객은 하나의 앱을 통해서 오픈뱅킹에 참여하는 모든 금융기관의 금융서비스를 통합하여 누릴 수 있어 고객의 편의성이 크게 제고 된다. 우리나라의 경우 금융결제망 개방을 통한 금융혁신 촉진과 고객 서비스 제고를 도 모하기 위해 2019년 12월 개인 고객을 대상으로 도입되었으며 2025년 1월에는 오픈뱅킹 이용자 범위를 법인까지 확대하였다.', related_words = '{}'::text[] WHERE id = 395;  -- 오픈뱅킹
UPDATE public.words SET meaning = '일본에서 낮은 금리로 엔화를 빌려 외화로 환전한 뒤 해외의 고금리 자산에 투자(일종의 yen carry trade)하는 일본의 중·상류층 주부 투자자들을 ‘와타나베(Watanabe)부인’이 라고', detailed_meaning = '일본에서 낮은 금리로 엔화를 빌려 외화로 환전한 뒤 해외의 고금리 자산에 투자(일종의 yen carry trade)하는 일본의 중·상류층 주부 투자자들을 ‘와타나베(Watanabe)부인’이 라고 하는데 일본의 개인 외환투자자들을 통칭하는 용어로 확장하여 사용하기도 한다. 이들은 일본의 장기불황(1991~2002년)과 저금리를 배경으로 2000년 무렵부터 등장하였다. 가정의 재정을 담당하는 일본 주부들은 낮은 저축이자에 실망하여 해외로 투자 기회를 찾아 엄청난 규모의 국제금융거래를 일으키며 외환시장을 좌지우지하는 세력으로 까지 성장하면서 글로벌 외환시장의 큰 손으로 통하기 시작하였다. 이들이 주로 사용하는 투자방식은 개인외환거래, 즉 FX(Foreign Exchange) 마진거래이다. 동 거래는 일정액의 증거금을 국내 선물회사나 중개업체에 맡겨두고 특정 해외통화의 변동성을 예측하여 두 종류의 통화를 동시에 사고파는 방식의 외환선물거래인데, 흔히 가치가 오를 것으로 예상되는 달러를 사는 동시에 가치가 떨어질 것으로 보이는 엔화를 매도하는 방식으로 이루어졌다.', related_words = '{}'::text[] WHERE id = 397;  -- 와타나베 부인
UPDATE public.words SET meaning = '완충자본(Buffer Capital)은 금융위기 시 은행이 손실을 흡수하거나 신용공급 기능을 지속(경기순응성 증폭을 억제)하면서도 최소 규제자본비율 수준 이상으로 자본비율을 유지하기에 충분한', detailed_meaning = '완충자본(Buffer Capital)은 금융위기 시 은행이 손실을 흡수하거나 신용공급 기능을 지속(경기순응성 증폭을 억제)하면서도 최소 규제자본비율 수준 이상으로 자본비율을 유지하기에 충분한 자본량을 의미하며, 바젤Ⅲ 규제개혁 시 도입한 것으로 최소 자기자본에 더하여 보통주자본으로 추가 적립하도록 요구하는 제도이다. 완충자본은 최소 자기자본비율에 대한 보완장치로서 이를 위반 시에는 적립비율을 충족할 때까지 이익배분(배당, 자사주 매입, 성과연동형 상여금 등)이 제한된다. 우리나라는 완충자본으로서 ① 손실흡수능력제고를 위한 자본보전완충자본(Capital Conservation Buffer, CCoB) ② 신용공급에 따른 경기순응성 완화를 위한 경기대응완충자본(Counter-Cyclical Buffer, CCyB)을 운용하고 있다. 자본보전완충자본은 위기시 손실 발생에 대비하기 위한 것으로 은행은 평상시 위험가중자산의 2.5%만큼을 추가 적립하여야 한다. 경기대응완충자본은 금융시스템 상황에 따라 완충자본을 탄력적으로 조정하는 정책수단으로 리스크가 완화되는 시기에는 경기대응완충자본을 적립하도록 하고 리스크가 확대되거나 금융불안이 발생하여 신용공급 축소가 우려되는 시기에는 은행들이 경기대응완충자본을 활용할 수 있도록 완충자본 부과 수준을 하향 조정한다. 우리나라는 2024년 5월부터 1%의 추가적립을 의무화하고 있다.', related_words = ARRAY['BIS 자기자본비율','기본자본(Tier 1)','보완자본(Tier 2)']::text[] WHERE id = 398;  -- 완충자본
UPDATE public.words SET meaning = '우리나라는 경제개발 초기에 외화자금이 크게 부족하였고 이에 대응해 국가 차원에서 외화자금을 효율적으로 조달·운용하기 위해 기업 등의 외환거래를 매우 엄격하게 규제하는 「외국환관리법」을 시행하였다.', detailed_meaning = '우리나라는 경제개발 초기에 외화자금이 크게 부족하였고 이에 대응해 국가 차원에서 외화자금을 효율적으로 조달·운용하기 위해 기업 등의 외환거래를 매우 엄격하게 규제하는 「외국환관리법」을 시행하였다. 그러나 1997년 외환위기 이후 IMF의 권고를 수용하여 민간부문의 경상거래 및 자본거래를 전면적으로 자유화하고 국가경제 측면에서 필요한 최소한의 사항만을 제한하는 「외국환거래법」을 도입하였다. 외국환관리법이 외환거래 및대외거래의 합리적 조정 또는 관리에 초점을 두었던 반면 외국환거래법은 외환거래 및 대외거래의 자유를 보장하고 시장기능을 활성화함으로써 대외거래의 원활화, 국제수지의균형 및 통화가치의 대외적 안정을 도모하는 데 치중하였다. 이후 2001년에 제1차 제2단계 조치를 실시하여 개인의 외환거래를 자유화하였으며, 2006년에는 제2차 외환자유화조치를 시행하여 자본거래 허가제를 폐지하고 신고제로 전환하였다. 한편 글로벌 금융위기 이후 외환시장의 안정과 외화유출의 급격한 변동성을 완화하기 위하여 외환건전성감독 강화 방안 시행, 외환건전성부담금제도 시행 등 유사시 시장안정장치를 마련하여 시행하고 있다.', related_words = ARRAY['국제수지(BOP)','자본거래자유화']::text[] WHERE id = 399;  -- 외국환거래법
UPDATE public.words SET meaning = '동아시아 외환위기, 글로벌 금융위기 등 우리나라가 겪었던 금융위기는 호황기에는 자본이 과도하게 유입되고 불황기에는 급격히 유출되는 자본유출입의 변동성에 주로 기인하였다.', detailed_meaning = '동아시아 외환위기, 글로벌 금융위기 등 우리나라가 겪었던 금융위기는 호황기에는 자본이 과도하게 유입되고 불황기에는 급격히 유출되는 자본유출입의 변동성에 주로 기인하였다. 이에 따라 정부와 한국은행은 금융·외환위기의 재발을 방지하기 위하여 과도한 자본유출입의 변동성을 제어하는 한편 우리 경제의 거시건전성을 제고하기 위한 방안으로 외환부문 거시건전성정책 수단을 도입하게 되었는데, 이의 일환으로 2011년 8월에 외환건전성부담금제도를 도입·시행하였다. 외환건전성부담금제도는 과도한 외화차입을 억제하고 외채구조의 장기화를 유도하기 위하여 은행의 비예금성외화부채(=전체외화부채-외화예수금-경과성자금 등)를 대상으로 계약 만기별로 0.02∼0.2%의 부담금을 부과하였으며 적립된 부담금은 외국환평형기금에 귀속되어 위기 시 금융기관에 대한 외화유동성지원에 활용되도록 하고 있다. 2015년 7월 금융업권 간 형평성을 제고하고 부과체계를 단순화하기 위하여 외환건전성부담금의 부과대상 및 부과요율 체계를 중심으로 제도를 개편하였으며, 현재는 만기 1년 이내의 비예금성외화부채에 대해 0.1%의 부담금을 부과 하고 있다.', related_words = ARRAY['외채/대외채권','외국환평형기금']::text[] WHERE id = 408;  -- 외환건전성부담금제도
UPDATE public.words SET meaning = '외환동시결제(PVP; Payment versus Payment)는 외환결제과정에서 국가간 결제시간대의 차이로 인하여 발생하는 외환결제리스크를 최소화하기 위하여 외환거래에 따른 수취 통화와', detailed_meaning = '외환동시결제(PVP; Payment versus Payment)는 외환결제과정에서 국가간 결제시간대의 차이로 인하여 발생하는 외환결제리스크를 최소화하기 위하여 외환거래에 따른 수취 통화와 지급통화를 동시에 주고 받는 결제방식으로서 대표적으로 CLS은행이 이러한 방식의 외환결제서비스를 제공하고 있다. 외환동시결제방식은 매수통화의 수취가 보장되는 경우에만 매도통화를 지급하기 때문에 거래당사자 일방이 파산 등의 이유로 매도통화를 지급하지 못했을 경우에는 매입통화의 지급도 일어나지 않아 외환결제리스크를 감축할수 있다.', related_words = ARRAY['외환결제리스크','Herstatt 리스크','CLS은행']::text[] WHERE id = 409;  -- 외환동시결제(PVP)
UPDATE public.words SET meaning = '외환보유액(Official Reserve Assets)은 중앙은행이나 정부가 국제수지 불균형을 보전하거나 외환시장 안정을 위해 언제든지 사용할 수 있도록 보유하고 있는 교환성이 있고 유동성이나', detailed_meaning = '외환보유액(Official Reserve Assets)은 중앙은행이나 정부가 국제수지 불균형을 보전하거나 외환시장 안정을 위해 언제든지 사용할 수 있도록 보유하고 있는 교환성이 있고 유동성이나 시장성이 높은 대외지급준비자산을 말한다. 그러므로 외환보유액은 긴급한 상황에서 쓰기 위해 갖고 있는 비상금과 같은 성격의 준비자산으로 외환보유액은 환율 급등 시 외환시장 안정을 위한 재원으로 이용될 뿐만 아니라 금융기관의 해외차입이 어려워지는 신용위기 상황에서 중앙은행 등이 최종대부자(last resort)의 역할을 하기 위한 재원이 된다. 이러한 목적에 부합하도록 현재 우리나라의 외환보유액은 선진국 국채 등 외화증권이나 예치금과 같은 유동성과 안정성이 높은 자산으로 운용되고 있다. 외환보유액은 경제위기 시 안전판 역할을 하여 국가 신용도를 높이고 중앙은행은 외화자산 운용에 따른 수익이 발생하는 등의 편익이 있지만 통화안정증권 등에 대한 이자지급 등 비용 또한 발생한다. 이처럼 외환보유의 편익과 기회비용이 동시에 발생하므로 외환보유액의 규모를 향후 발생 가능한 외부충격에 대한 완충 역할을 하는데 부족하지 않은 수준으로 적정 관리할 필요가 있다.', related_words = ARRAY['대외지급준비자산','특별인출권(SDR)']::text[] WHERE id = 410;  -- 외환보유액
UPDATE public.words SET meaning = '외환스왑거래란 거래당사자들이 현재의 계약환율에 따라 서로 다른 통화를 교환하고 일정 기간 후 최초 계약 시점에서 정한 선물환율에 따라 원금을 재교환하는 거래를 말한다.', detailed_meaning = '외환스왑거래란 거래당사자들이 현재의 계약환율에 따라 서로 다른 통화를 교환하고 일정 기간 후 최초 계약 시점에서 정한 선물환율에 따라 원금을 재교환하는 거래를 말한다. 즉 외환스왑거래는 동일한 거래상대방 간에 현물환과 선물환 또는 만기가 상이한 선물환과 선물환, 현물환과 현물환을 서로 반대 방향으로 동시에 매매하는 거래를 의미하며 스왑기간 중 이자 지급은 없으나 계약 시 통화 간 이자율 차가 반영되어 만기 시 환율이 산정된다. 외환스왑거래에 있어 매입·매도는 원일물(far date)거래를 기준으로 구분된다. 예를 들면 우리나라에서 외환스왑 매입은 달러화를 기준으로 근일물을 매도하고 원일물을 매입하는 sell&buy swap거래를 말하며 외환스왑 매도는 근일물을 매입하고 원일물을 매도하는 buy&sell swap거래를 의미한다. 외환스왑의 거래동기를 보면 자금조달, 환리스크의 관리, 결제일의 조정, 금리차익 획득 및 금리변동을 이용한 투기적 거래 등의 목적으로 나누어 볼 수 있다.', related_words = ARRAY['스왑','선물환거래','통화스왑']::text[] WHERE id = 411;  -- 외환스왑거래
UPDATE public.words SET meaning = '외환시장은 좁은 의미에서 외환의 수요와 공급이 연결되는 장소를 말하나 넓은 의미에서 는 이러한 장소적 개념뿐 아니라 외환거래의 형성, 결제 등 외환거래가 정기적 또는 지속적으로 이루어지는 일련의', detailed_meaning = '외환시장은 좁은 의미에서 외환의 수요와 공급이 연결되는 장소를 말하나 넓은 의미에서 는 이러한 장소적 개념뿐 아니라 외환거래의 형성, 결제 등 외환거래가 정기적 또는 지속적으로 이루어지는 일련의 메커니즘을 포괄한다. 외환시장은 기본적으로 서로 다른 통화로 표시된 지급수단의 매매가 이루어지는 시장(market for means of payments)으로서 외화자금의 대차가 이루어지는 외화자금시장과는 그 성격을 달리한다. 외환시장에서의 서로 다른 통화 간의 매매는 기본적으로 상품과 용역 그리고 금융자산의 매매거래에 수반하여 일어나기 때문에 이들 외환거래는 기본적으로 지급 메커니즘의 한 과정으로 이해할수 있다. 따라서 각국의 금융시장이나 유로금융시장에서 이루어지는 서로 다른 통화로 표시된 금융거래는 외환시장의 거래와 연계되어 이루어진다. 오늘날 국제외환시장은 세계주요 외환시장의 거래를 24시간 연계시키면서 모든 시장정보를 환율에 신속하게 그리고 지속적으로 반영하는 하나의 범세계적 시장으로서의 기능을 수행하면서 국제금융거래의 효율화를 촉진하고 있다.', related_words = ARRAY['외화자금시장']::text[] WHERE id = 412;  -- 외환시장
UPDATE public.words SET meaning = '1997년 외환위기 이후 우리나라가 주식·채권시장을 전면 개방하고 외국인직접투자도 전면 허용하는 등 외환거래 자유화조치를 취함에 따라, 국외 여건 변화에 따른 빈번한 외자유출입 등으로 우리 경제의', detailed_meaning = '1997년 외환위기 이후 우리나라가 주식·채권시장을 전면 개방하고 외국인직접투자도 전면 허용하는 등 외환거래 자유화조치를 취함에 따라, 국외 여건 변화에 따른 빈번한 외자유출입 등으로 우리 경제의 변동성이 확대될 가능성이 크게 높아졌다. 이러한 위험에 효과적으로 대처할 수 있도록 외환거래 정보를 집중하고 이용할 수 있는 인프라의 구축필요성이 제기됨에 따라 정부는 1999년 3월 한국은행을 외환정보집중기관으로 지정하였고, 한국은행은 1999년 4월 외환거래 및 시장정보를 신속하게 수집·분석할 수 있는 외환정보시스템(FEIS; Foreign Exchange Information System, 이하 ‘외환전산망’)을 구축하였다. 외환전산망에는 외국환업무취급기관들이 실행한 외환거래 관련 통계 등 정보가 집중되며 한국은행은 이를 취합하여 기획재정부, 금융위원회, 국세청, 관세청, 금융정보분석원, 금융감독원 등 여러 이용기관들에게 신속하게 제공하고 있다. 한국은행은 외환전산망 자료를 활용해 국내외 외화자금 유출입 동향 등에 대한 신속한 모니터링과 시장안정을 위한 대응방안 마련, 국제수지·외채 등 주요 외환통계의 작성, 각종 불법적인 외환거래조사 등의 업무를 수행하고 있다.', related_words = ARRAY['국제수지(BOP)','외채/대외채권']::text[] WHERE id = 413;  -- 외환전산망
UPDATE public.words SET meaning = '요소비용에 의한 국민소득(NI at factor cost)은 통상 국민소득(NI)이라 불리며 한 나라의 국민이 제공한 생산요소에서 발생한 소득의 총액, 즉 노동에 대한 대가인 피용자보수와 토지,', detailed_meaning = '요소비용에 의한 국민소득(NI at factor cost)은 통상 국민소득(NI)이라 불리며 한 나라의 국민이 제공한 생산요소에서 발생한 소득의 총액, 즉 노동에 대한 대가인 피용자보수와 토지, 자본, 경영에 대한 대가인 영업잉여의 합계로서 고정자본소모와 순생산 및 수입세가 포함되지 않으므로 한 나라 국민이 벌어들인 순수한 소득을 나타내는 지표이다.요소비용에 의한 국민소득 = 시장가격에 의한 국민소득 - 생산 및 수입세 + 보조금 =피용자보수 + 영업잉여의 관계가 성립한다.', related_words = ARRAY['영업잉여','피용자보수']::text[] WHERE id = 415;  -- 요소비용 국민소득
UPDATE public.words SET meaning = '우발전환사채(Contingent Convertible Bond)는 발행기관이 경영개선명령을 받거나 부실금융기관으로 지정될 경우 상각되거나 보통주로 전환되는 조건이 부가되어 있는 채권', detailed_meaning = '우발전환사채(Contingent Convertible Bond)는 발행기관이 경영개선명령을 받거나 부실금융기관으로 지정될 경우 상각되거나 보통주로 전환되는 조건이 부가되어 있는 채권 (조건부자본증권)을 말한다. 이러한 조건이 실현될 경우 코코본드는 강제로 상각되거나 주식으로 전환되기 때문에 발행기관의 채무부담은 줄어들고 자본은 확충된다. 채권이 상각될 경우 투자자가 원금손실을 입게 되는 위험을 반영하여 코코본드의 발행금리는 일반회사채보다 다소 높게 형성된다. 최근 코코본드의 발행이 늘어난 것은 공급측면에서 무엇보다 바젤Ⅲ 시행에 따른 은행권의 자본확충 필요성이 증가한 데 기인한다. 바젤Ⅲ에서 는 금융기관 자본의 인정요건을 종전보다 강화하였는데, 특히 후순위채권 등에 대해서는 유사시 주식으로 전환되거나 상각되는 조건부자본 요건을 추가로 충족하도록 요구하고 있다. 바젤Ⅲ 규제 하에서 금융기관 입장에서는 코코본드를 발행하게 되면 자본이 증가 해 건전성지표인 자기자본비율이 개선되는 효과가 있다. 수요측면에서 보면, 코코본드는 지속되는 저금리 상황에서 일반 채권보다 금리가 높은 데다 이자지급이 보장되는 후순위채 위주로 발행됨에 따라 투자메리트가 높은 편이다. 코코본드 발행은 유사시 손쉽게 자본을 확충하는 이점이 있으나 발행기관의 자본조달비용을 증가시키는 효과도 있으므로 적정수준에서 관리될 필요가 있다.', related_words = ARRAY['자기자본비율']::text[] WHERE id = 417;  -- 우발전환사채(코코본드)
UPDATE public.words SET meaning = '1990년대 미국이 중남미 국가들에 대해 제시하였던 미국식 시장경제체제의 확산 전략을 뜻하며 미국이 주도하는 신자유주의의 대명사로도 인식되고 있다.', detailed_meaning = '1990년대 미국이 중남미 국가들에 대해 제시하였던 미국식 시장경제체제의 확산 전략을 뜻하며 미국이 주도하는 신자유주의의 대명사로도 인식되고 있다. 이 용어는 1989년 미국 국제경제연구소의 정치경제학자 존 윌리엄슨이 당시 경제위기로 어려움을 겪고 있던 중남미 국가들에 대한 개혁 처방을 워싱턴 컨센서스(Washington Consensus)로 명명한 데서 유래하였고 1990년대 초 미국의 재무부, 국제통화기금(IMF), 세계은행(World Bank) 등 미국 워싱턴에 있는 기관들의 논의를 거치면서 그 개념이 정립되었다. 워싱턴컨센서스는 개발도상국, 체제전환국, 제3세계 국가들이 시행해야 할 구조조정 정책으로 서 정부예산 삭감, 자본시장 자유화, 외환시장 개방, 관세 인하, 국가 기간산업 민영화, 외국자본에 의한 국내기업 합병ㆍ매수 허용, 정부 규제 축소, 재산권 보호 등을 제시하고 있다. 실제로 이러한 정책들은 동구 사회주의국가의 체제 전환과 1990년대 후반 아시아의 외환위기 극복과정에서 채택되었다. 워싱턴 컨센서스에 대해서는 세계의 경제시스템을 미국의 자본과 기업이 진출하기 쉽게 만들어 미국의 이익을 증진시키기 위한 것이라는 비판도 있다.', related_words = ARRAY['국제통화기금(IMF)','세계은행(World Bank)','동아시아 외환위기']::text[] WHERE id = 419;  -- 워싱턴 컨센서스
UPDATE public.words SET meaning = '원/위안 직거래시장은 달러를 매개로 하지 않고 원화를 위안화로, 위안화를 원화로 바로 환전할 수 있는 시장을 의미한다.', detailed_meaning = '원/위안 직거래시장은 달러를 매개로 하지 않고 원화를 위안화로, 위안화를 원화로 바로 환전할 수 있는 시장을 의미한다. 2014년 7월 한·중 정상이 양국 간 자국 통화 거래를 활성화하는 것이 서로에게 이익이 된다는 데 인식을 같이하고 한ㆍ중 무역 및 금융거래에 서 위안화 활용도를 제고하기 위한 정책과제의 하나로 원/위안 직거래시장을 개설하기로 합의함에 따라 서울외환시장 운영협의회를 중심으로 중개시스템 개발, 시장조성자 제도 도입 등을 추진하여 2014년 12월 원/위안 직거래시장을 공식 개설하였다. 또한 2015년 10월 양국 정상회담을 통해 상하이 원/위안 직거래시장을 조속한 시일 내에 개설하기로 합의하였고 이에 따라 2016년 6월 27일 상하이 원/위안 직거래 시장이 개설되었다. 원/ 위안 직거래시장은 우리 경제 전반에 다양한 경제적 효과를 미친다. 우선 기업 등 고객은 미달러화의 매개 없이 원화와 위안화를 직거래함으로써 환전수수료 등 거래비용을 절감할 수 있다. 결제통화 다변화를 통해 미달러화 의존도가 낮아질 경우 미달러화 자금사정에 대한 우리경제의 민감도를 낮출 수 있다. 원/위안 직거래시장은 개설 이후 높은 관심과 시장조성은행들의 적극적거래 등에 힘입어 일평균 거래량이 30억 달러를 넘어서고 호가 스프레드도 경쟁적으로 형성되는 등 시장형성에 비교적 성공한 것으로 평가되고 있다.', related_words = ARRAY['외환시장']::text[] WHERE id = 421;  -- 원/위안 직거래시장
UPDATE public.words SET meaning = '외환결제리스크 중 가장 대표적인 리스크로 매도통화를 이미 지급하였거나 매도통화의 지급을 취소할 수 없는 상황에서 거래상대방이 파산하는 경우 매입통화를 전액 수취하지못하는 리스크를', detailed_meaning = '외환결제리스크 중 가장 대표적인 리스크로 매도통화를 이미 지급하였거나 매도통화의 지급을 취소할 수 없는 상황에서 거래상대방이 파산하는 경우 매입통화를 전액 수취하지못하는 리스크를 원금리스크(Principal Risk)라고 한다. 환거래가 양방향으로 일어난다는 점과 주로 국경을 넘어 발생한다는 특성으로 인하여 매입통화와 매도통화의 결제가 동시에 이루어지지 않기 때문에 원금리스크가 발생하게 된다.', related_words = ARRAY['외환결제리스크','Herstatt 리스크']::text[] WHERE id = 422;  -- 원금리스크
UPDATE public.words SET meaning = '단기채무에 충당할 수 있는 유동자산이 얼마나 되는가를 평가하여 기업의 단기지급능력을 판단할 수 있는 대표적 지표로서 유동비율이 높을수록 단기지급능력이 양호하다고 볼수 있으나 과다한 유동자산 보유는', detailed_meaning = '단기채무에 충당할 수 있는 유동자산이 얼마나 되는가를 평가하여 기업의 단기지급능력을 판단할 수 있는 대표적 지표로서 유동비율이 높을수록 단기지급능력이 양호하다고 볼수 있으나 과다한 유동자산 보유는 자산운용 효율성을 떨어뜨려 수익성을 저해한다. 유동비율 = 유동자산/유동부채 × 100', related_words = '{}'::text[] WHERE id = 427;  -- 유동비율
UPDATE public.words SET meaning = '유동성커버리지비율(LCR; Liquidity Coverage Ratio)은 단기 유동성 규제비율로서 은행이 유동성 부족에 대비하여 보유한 고유동성자산 규모를 30일간의 유동성스트레스 시나 리오', detailed_meaning = '유동성커버리지비율(LCR; Liquidity Coverage Ratio)은 단기 유동성 규제비율로서 은행이 유동성 부족에 대비하여 보유한 고유동성자산 규모를 30일간의 유동성스트레스 시나 리오 하에서 예상되는 순현금유출액으로 나눈 비율이다. LCR의 산식은 ‘고유동성자산 / ㅇ향후 30일간 순현금유출액(현금유출액 - 현금유입액) × 100’이다. 분자의 고유동성자산은 현금은 물론 정부 및 중앙은행이 발행하는 채무증권, 은행이 중앙은행에 예치한 지급준비금 등으로 구성된다. 분모의 순현금유출액은 30일 동안의 심각한 위기상황에서 발생할 것으로 예상되는 현금유출액에서 현금유입액을 차감하여 산출한다. 일반은행이 준수해야 하는 LCR 규제비율은 2015년 80%에서 2019년 100%로 점진적으로 도입되었다. 코로나19 사태 이후 금융권의 가계대출 및 기업 자금 공급 확대를 위해 2020년 일시적으로 기존 100%에서 85%로 인하하였으나 2022년부터 단계적 상향을 통해 2025년 7월 말 현재 100%를 준수하여야 한다.', related_words = ARRAY['유동성리스크','순안정자금조달비율']::text[] WHERE id = 430;  -- 유동성커버리지비율
UPDATE public.words SET meaning = 'EBRD(European Bank for Reconstruction and Development)는 중·동부 유럽 국가 의 시장경제체제로의 전환 촉진과 경제개발 지원을 목적으로 1991년 3월', detailed_meaning = 'EBRD(European Bank for Reconstruction and Development)는 중·동부 유럽 국가 의 시장경제체제로의 전환 촉진과 경제개발 지원을 목적으로 1991년 3월 설립된 국제금융기구로서 영국 런던에 본부를 두고 있다. 주요 업무는 역내 회원국에 대한 생산적이고 경쟁적인 민간부문의 활동 지원, 경제개발을 위한 역내외 자본 및 선진기술 동원, 경쟁여건 조성과 생산성 향상을 위한 투자 촉진, 개발사업계획 관련 기술지원 등이다. 재원은 자본금, 채권 발행 및 차입금으로 조성되는 일반재원과 출연을 통한 특별재원으로 조달하고 조직은 총회, 이사회 및 총재를 비롯한 집행부로 구성되어 있다. 2025년 7월 말 현재회원국은 총 77개국이며 역내 국제기구인 유럽연합(EU)과 유럽투자은행(EIB; European Investment Bank)에도 회원자격을 부여하고 있다. 우리나라는 창립회원국으로 참여하고 있다.', related_words = ARRAY['유럽연합(EU)']::text[] WHERE id = 431;  -- 유럽부흥개발은행(EBRD)
UPDATE public.words SET meaning = '유럽연합(EU; European Union)은 1991년 12월 마스트리히트 유럽이사회에서 유럽공동체(EC) 12개국 정상이 유럽통합의 방향과 주요 원칙에 합의한 뒤, 1992년 2월', detailed_meaning = '유럽연합(EU; European Union)은 1991년 12월 마스트리히트 유럽이사회에서 유럽공동체(EC) 12개국 정상이 유럽통합의 방향과 주요 원칙에 합의한 뒤, 1992년 2월 마스트리히트조약(Treaty on European Union)에 서명하고 1993년 11월 동 조약이 발효되면서 종전의 유럽공동체를 계승하는 지역공동체로 공식 출범하였다. 창설 목적은 유럽 내단일시장 구축 및 단일통화 실현을 통한 유럽의 경제와 사회발전 촉진, 공동외교안보정책을 통한 국제무대에서의 유럽의 이익 제고, 유럽연합 시민권제도 도입에 의한 회원국 국민의 권리와 이익 보호 등이다. 회원국은 1995년 1월 3개국이 추가 가입한 데 이어 동유럽 체제전환국들이 가입하면서 점차 늘어났으나 2020년 1월 영국이 EU에서 탈퇴함으로 써 2025년 현재 총 27개국의 회원국이 있다. 유럽연합의 주요 기구는 회원국 정상들의 회의체인 유럽이사회(European Council), 각종 정책 입안 및 집행을 담당하는 집행위원회(European Commission), 회원국 간 문제해결을 위한 장관들의 회의체인 각료이사회 (CEU), 유럽의회(EP) 등이며 그 외에 유럽사법재판소, 유럽회계감사원, 지역위원회, 유럽중앙은행(ECB), 유럽투자은행 등이 있다. 유럽연합은 유럽의회가 입법부, 유럽사법재판소가 사법부, 집행위원회가 행정부의 역할을 하는 등 일반적인 국제기구와는 달리 독자적인 법령 체계와 입법·사법·행정 기능을 갖추고 있다.', related_words = ARRAY['유럽중앙은행(ECB)','마스트리히트조약']::text[] WHERE id = 432;  -- 유럽연합(EU)
UPDATE public.words SET meaning = '유통시장(또는 제2차 시장, Secondary Market)은 이미 발행된 채권, 주식 등 유가증권이 투자자들 사이에서 매매되는 시장을 말한다.', detailed_meaning = '유통시장(또는 제2차 시장, Secondary Market)은 이미 발행된 채권, 주식 등 유가증권이 투자자들 사이에서 매매되는 시장을 말한다. 유통시장은 발행시장에서 발행된 유가증권의 시장성과 환금성을 높여주고 자유경쟁을 통해 공정한 가격을 형성하는 기능을 한다. 채권 유통시장은 장외시장과 장내시장으로 구분된다. 현재 대부분의 채권거래는 장외시장에서 주로 증권회사의 단순중개를 통하여 이루어지고 있다. 장내시장으로는 한국거래소 내에 일반채권시장과 국채전문유통시장이 개설되어 있다. 일반채권시장에서 는 전환사채와 소액 국공채의 장내거래가 의무화되어 있어 채권 거래가 비교적 활성화되어 있다. 국채전문유통시장에서의 거래는 국고채전문딜러의 지속적이고 유효한 호가 제시를 통한 시장조성 의무 강화 등의 제도 개선 노력에 힘입어 증가하고 있다. 주식 유통시장에는 유가증권시장(코스피시장), 코스닥시장, 코넥스시장 및 K-OTC시장이 있다. 이 중 K-OTC시장은 장외시장이며, 나머지는 한국거래소에서 개설·운영하는 장내시장이다. 주식이 장내시장에서 매매되기 위해서는 상장이라는 등록 절차를 거쳐야 한다. 코스닥시장은 유망 중소기업, 벤처기업 등이 진입하는 시장이다. 코넥스시장은 설립 초기 중소기업에 특화된 시장으로, 2013년 7월 개설 당시에는 코스닥시장의 하부시장 형태였으나, 2013년 9월 별도시장으로 분리되었다. K-OTC시장에서는 비상장 주식이 거래된다.', related_words = ARRAY['발행시장','채권시장','주식시장']::text[] WHERE id = 436;  -- 유통시장
UPDATE public.words SET meaning = '은행권의 위조방지를 위한 장치의 하나로 은행권용지에 삽입된 플라스틱 또는 금속으로 된 가는 선형필름을 말하며, 삽입된 필름의 문양 또는 글자 등을 확인할 수 있다.', detailed_meaning = '은행권의 위조방지를 위한 장치의 하나로 은행권용지에 삽입된 플라스틱 또는 금속으로 된 가는 선형필름을 말하며, 삽입된 필름의 문양 또는 글자 등을 확인할 수 있다. 은 선(Security Thread)에는 현용 천원권과 같이 숨고 드러나기를 반복하는 부분노출은선과 오천원권, 만원권과 같이 용지 속에 완전히 삽입된 숨은 은선이 있다. 또 오만원권처럼 숨은 은선과 부분노출은선이 같이 있는 경우도 있다. 숨은 은선에는 주로 미세문자를 삽입하거나 보는 각도에 따라 색상이 변하는 필름을 적용한다. 오만원권에는 초상 오른쪽에 숨겨져 있는 특수 필름띠 위에 문자와 액면 숫자 “한국은행 BANK OF KOREA 50000”이 보이며, 만원권·오천원권에는 액면 숫자만 다르게 표시되어 있다. 그리고 오만 원권의 부분노출은선은 청회색 특수 필름 띠로, 여러 개의 태극무늬가 사방 연속으로 새겨져 있으며 은행권을 상하로 움직이면 태극무늬가 좌우로, 은행권을 좌우로 움직이면 태극무늬가 상하로 움직이는 것처럼 보여 ‘Motion’이라 부른다. 한편 천원권에는 숨은 은선은 없고 가운데 부분에 부분노출은선이 있다.', related_words = ARRAY['숨은 그림(은화)']::text[] WHERE id = 437;  -- 은선
UPDATE public.words SET meaning = '은행인수어음(BA; Banker’s Acceptance)은 은행의 단기무역신용공급방식의 하나로 수출입대금결제를 위해 발행된 환어음을 은행이 인수(accept)하는 것을 말하며, 은행이 어음상의', detailed_meaning = '은행인수어음(BA; Banker’s Acceptance)은 은행의 단기무역신용공급방식의 하나로 수출입대금결제를 위해 발행된 환어음을 은행이 인수(accept)하는 것을 말하며, 은행이 어음상의 지급의무를 부담한 것이므로 그 신용도가 높아 시장에서 자유로이 양도되고 자산보유의 형태로도 이용되고 있다. 통상 어음발행인이 인수은행에 매입을 신청하고 할인받는 것이 관행으로 되어 있으며, 미국에서는 일반적으로 인수은행이 BA를 만기일까지 보유하지 않고 유통시장에 매각함으로써 안정성과 유동성이 뛰어난 독특한 시장이 형성되는데 이를 은행인수어음시장이라 한다.', related_words = '{}'::text[] WHERE id = 439;  -- 은행인수어음(BA)
UPDATE public.words SET meaning = '외국은행 국내지점의 동일인 및 동일계열기업군 여신한도 등 은행법상의 영업규제와 관련하여 자기자본을 확대해줌으로써 여신기능이 원활히 수행될 수 있도록 하기 위한 명목상의 자본금으로 대차대조표에는', detailed_meaning = '외국은행 국내지점의 동일인 및 동일계열기업군 여신한도 등 은행법상의 영업규제와 관련하여 자기자본을 확대해줌으로써 여신기능이 원활히 수행될 수 있도록 하기 위한 명목상의 자본금으로 대차대조표에는 나타나지 않는다. 현재 을기금은 「은행업 감독규정」 제 11조에 의거 외국은행 국내지점이 외화자금을 환매조건부로 한국은행에 매각하여 보유· 운용하는 원화자금과 외은지점이 자행의 본점 또는 국외지점으로부터 상환기간이 1년을 초과하는 조건으로 차입한 자금 중 국내에서 운용하는 자금(본지점 장기차입금)을 합산한 것으로 하되 대차대조표상 자본총계의 200%를 초과할 수 없도록 규정하고 있다.', related_words = ARRAY['갑기금(Capital A)']::text[] WHERE id = 440;  -- 을기금(Capital B)
